window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["E1"]={"deck":"E1","slides":[{"p":1,"title":"표지: 1강 친환경건축의 개념 및 정의","terms":["Eco-friendly Architecture","Ecology"],"pass1":[{"kind":"say","lines":["1강이 시작돼요. 제목은 '친환경건축의 개념 및 정의' 예요.","오늘 배울 것은 기술이 아니라 **친환경건축(Eco-friendly Architecture)** 이 왜 나왔는지예요.","이 과목을 관통하는 주문을 먼저 외워요.","자연에서 빌려 쓰고, 돌려주며 순환시켜요."]},{"kind":"figure","head":"오늘 갈 길 네 덩어리","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"14\" y=\"40\" width=\"104\" height=\"54\" rx=\"2\" class=\"box b1\"/><text x=\"66\" y=\"64\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">들어가며<\/text><text x=\"66\" y=\"84\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">배경<\/text><line x1=\"120\" y1=\"67\" x2=\"127\" y2=\"67\" class=\"e2 b2\"/><polygon points=\"136,67 127,72 127,62\" class=\"arrow b2\"/><rect x=\"138\" y=\"40\" width=\"104\" height=\"54\" rx=\"2\" class=\"box b2\"/><text x=\"190\" y=\"64\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">인문적 배경<\/text><text x=\"190\" y=\"84\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">두 세계관<\/text><line x1=\"244\" y1=\"67\" x2=\"251\" y2=\"67\" class=\"e2 b3\"/><polygon points=\"260,67 251,72 251,62\" class=\"arrow b3\"/><rect x=\"262\" y=\"40\" width=\"104\" height=\"54\" rx=\"2\" class=\"box2 b3\"/><text x=\"314\" y=\"64\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">순환 설계<\/text><text x=\"314\" y=\"84\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">다섯 순환<\/text><line x1=\"368\" y1=\"67\" x2=\"375\" y2=\"67\" class=\"e2 b4\"/><polygon points=\"384,67 375,72 375,62\" class=\"arrow b4\"/><rect x=\"386\" y=\"40\" width=\"82\" height=\"54\" rx=\"2\" class=\"box b4\"/><text x=\"427\" y=\"64\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b4\">공동체<\/text><text x=\"427\" y=\"84\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b4\">사례<\/text><text x=\"240\" y=\"150\" font-size=\"16\" text-anchor=\"middle\" class=\"tb b4\">왜 필요한가 → 어떤 생각인가 → 어떻게 하는가<\/text><text x=\"240\" y=\"182\" font-size=\"16\" text-anchor=\"middle\" class=\"tm b4\">자연에서 빌려 쓰고, 돌려주며 순환시켜요<\/text><\/svg>","caption":"표지 아래 두 줄이 그대로 오늘의 차례예요. 마지막 사례는 가볍게 보고 지나가요.","builds":4}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"네 덩어리를 쉬운 말로 바꾸면","items":["들어가며: **친환경건축(Eco-friendly Architecture)** 이 왜 나왔는지, 그 배경이에요.","인문적 배경: 어떤 생각에서 나왔는지예요. **생태학(Ecology)** 이 여기서 나와요.","순환을 고려한 설계: 실제로 어떻게 하는지예요. 다섯 가지 순환을 배워요.","친환경공동체 사례: 다 배운 것을 실제 단지에서 보는 마무리예요."]},{"kind":"prof","when":"2주차 목요일 수업","lines":["오늘은 친환경건축의 학술적 의미를 개괄하는 마지막 날이라고 하셨어요.","다음 주부터는 세부 기술이 나오니 전체를 훑는 것은 오늘이 마지막이래요.","목차로 구조를 먼저 잡고 세부 내용을 하나씩 보겠다고 하셨어요."]},{"kind":"prof","when":"2주차 목요일 수업","lines":["반 학기 동안 배울 것은 다섯 가지래요. 에너지, 재료, 녹지, 물, 대기예요.","마지막 친환경공동체 사례는 영상으로 볼 뿐 시험에 내지 않겠다고 하셨어요.","시험 범위는 교재 43쪽 위까지라고 못박으셨어요."]}],"pass3":[{"kind":"check","q":"이 강의에서 계속 돌아오는 다섯 가지 순환 대상은 무엇일까요?","choices":["에너지, 재료, 녹지, 물, 대기","빛, 소리, 열, 공기, 물","벽, 지붕, 바닥, 창, 문"],"a":0,"why":"교수님이 반 학기 동안 배울 것이라고 짚어 주신 다섯 가지가 에너지, 재료, 녹지, 물, 대기예요."},{"kind":"warn","head":"표지에서 알아 둘 점","items":["표지 목차에는 '친환경공동체 사례' 가 있지만 46쪽짜리 강의자료 안에는 그 쪽이 없어요.","교수님도 사례는 영상으로 보여 주고 시험에는 내지 않겠다고 하셨어요.","**친환경건축(Eco-friendly Architecture)** 은 기술 이름이 아니라 태도를 가리키는 말이에요. 주문을 기억해요."]}],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.102,0.398,0.797,0.082],"c":[0.0622,0.3504,0.8767,0.1771],"r":6.6004,"img":"img/E1/walk/p001_20_01.jpg","say":"큰 제목이에요. 1강의 이름은 '친환경건축의 개념 및 정의' 예요."},{"b":[0.207,0.573,0.568,0.031],"c":[0.1786,0.5254,0.6248,0.1262],"r":6.6012,"img":"img/E1/walk/p001_20_02.jpg","say":"첫 줄: 들어가며(친환경건축의 배경) / 친환경건축의 인문적 배경"},{"b":[0.232,0.645,0.518,0.029],"c":[0.2061,0.6019,0.5698,0.1151],"r":6.6006,"img":"img/E1/walk/p001_20_03.jpg","say":"둘째 줄: 순환을 고려한 친환경건축 설계 / 친환경공동체 사례"}]}},{"p":2,"title":"친환경건축의 배경: 무엇을 반성하며 나왔을까요","terms":["Eco-friendly Architecture","Ecology","Domination of Nature","Capitalism","Industrial Revolution","Global Ecological Crisis","Limits to Growth","Rio Conference","Kyoto Protocol"],"pass1":[{"kind":"say","lines":["**친환경건축(Eco-friendly Architecture)** 은 반성문이에요.","옛날 건축이 자연을 너무 함부로 썼다는 것을 반성하며 나왔어요.","반성의 대상 이름이 **자연 지배관(Domination of Nature)** 이에요.","그래서 오늘의 주문은 이렇게 시작해요. 자연에서 빌려 쓰고, 돌려주며 순환시켜요."]},{"kind":"analogy","head":"용돈을 펑펑 쓴 뒤에 쓰는 반성문","scene":"용돈이 끝없는 줄 알고 마구 썼더니 통장도 바닥나고 몸도 망가졌어요. 그래서 반성문을 쓰고 새 계획을 세워요.","map":[["마음대로 써도 된다는 버릇","**자연 지배관(Domination of Nature)**"],["뒤에서 부추긴 친구","**자본주의(Capitalism)**"],["바닥난 통장, 망가진 몸","**전지구적 생태위기(Global Ecological Crisis)**"],["반성문과 새 계획","**친환경건축(Eco-friendly Architecture)**"]]}],"pass2":[{"kind":"points","head":"먼저 용어 하나하나의 뜻이에요","items":["**자연 지배관(Domination of Nature)**: 사람이 자연을 정복하고 마음대로 부려도 된다는 생각이에요.","**자본주의(Capitalism)**: 돈과 이익을 늘리는 쪽으로 움직이는 경제 방식이에요.","**산업혁명(Industrial Revolution)**: 기계로 물건을 많이 만들며 근대화, 산업화가 일어난 큰 변화예요.","**전지구적 생태위기(Global Ecological Crisis)**: 지구 전체의 자연과 사람이 함께 살아남기 어려워진 위기예요."]},{"kind":"look","walked":1},{"kind":"points","head":"**생태학(Ecology)** 이 무엇인지 한 줄로","items":["**생태학(Ecology)** 은 생물체끼리 서로 어떤 관계인지 연구하는 학문이에요.","슬라이드 첫 줄의 '생태학적 인식' 은 인공환경보다 자연환경이 중요하다는 눈이에요.","**친환경건축(Eco-friendly Architecture)** 은 바로 이 눈에서 출발했어요."]},{"kind":"prof","when":"2주차 목요일 수업","lines":["친환경건축은 인공환경보다 자연환경의 중요성을 인식하는 생태학적 인식에서 출발한다고 하셨어요.","반성의 대상은 17세기 과학자와 사상가들이 만든 자연 지배관이래요.","뉴턴이나 데카르트 같은 이름은 외우지 않아도 된다고 하셨어요.","자본주의가 부채질하고 18세기 산업혁명으로 터졌다고 정리해 주셨어요."]},{"kind":"prof","when":"2주차 목요일 수업","lines":["70년대에 로마에서 성장의 한계를 처음 눈치챘고 100년을 못 갈 것 같다는 말이 나왔대요.","92년 브라질 리우에서 각국 대표가 모여 환경회의를 했어요.","97년 일본 교토에서 의정서를 발표했고, 온실가스를 규제하자는 말이 여기서 처음 나왔대요.","연도를 세밀하게 외우기보다 17세기, 18세기, 70년대, 92년, 97년 흐름을 알면 좋대요."]}],"pass3":[{"kind":"check","q":"**자연 지배관(Domination of Nature)** 을 키운 세 가지에 들어가지 않는 것은?","choices":["인간에 의한 자연지배와 물질의 무한 이용","자본주의의 지원","산업혁명의 근대화, 산업화 효과","지역 특성에 맞춘 건축 양식"],"a":3,"why":"지역 특성에 맞춘 것은 다음 쪽의 토속건축이에요. 슬라이드의 세 가지는 무한 이용, **자본주의(Capitalism)**, **산업혁명(Industrial Revolution)** 예요."},{"kind":"check","q":"위기 인식이 시작된 계기를 슬라이드 순서대로 고르면?","choices":["성장의 한계 → 리우환경회의(92년) → 교토의정서(97년)","리우환경회의 → 성장의 한계 → 교토의정서","교토의정서 → 리우환경회의 → 성장의 한계"],"a":0,"why":"**성장의 한계(Limits to Growth)** 가 먼저고, **리우환경회의(Rio Conference)** 가 1992년, **교토의정서(Kyoto Protocol)** 가 1997년이에요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"친환경건축은 자연환경의 중요성에 대한 생태학적 인식에서 출발하여, 근대 이후의 건축양상에 대한 반성으로 나타난 새로운 건축적 대안이다.","ko":"출발점은 생태학적 인식, 반성의 대상은 17세기의 자연 지배관이에요.","tip":"'생태학적 인식에서 출발, 근대 이후 반성, 새 대안' 세 도막으로 끊어 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**자연 지배관(Domination of Nature)** 은 17세기의 생각이고 **산업혁명(Industrial Revolution)** 은 18세기의 사건이에요. 순서를 바꾸지 마세요.","결과를 쓸 때 빈곤 해방만 쓰면 안 돼요. 생존 위협까지 함께 써야 해요.","**리우환경회의(Rio Conference)**(1992년) 가 먼저, **교토의정서(Kyoto Protocol)**(1997년) 가 나중이에요."]}],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.063,0.102,0.227,0.036],"c":[0.051,0.065,0.251,0.11],"r":3.0424,"img":"img/E1/walk/p002_21_01.jpg","say":"소제목이에요. 이 쪽은 '친환경건축의 배경' 을 다뤄요."},{"b":[0.117,0.23,0.791,0.093],"c":[0.0775,0.1886,0.8701,0.1758],"r":6.5992,"img":"img/E1/walk/p002_21_02.jpg","say":"출발점 두 줄이에요. 자연환경의 중요성에 대한 생태학적 인식에서 출발했고, 근대 이후 건축에 대한 반성으로 새 대안이 됐어요."},{"b":[0.118,0.35,0.612,0.092],"c":[0.0874,0.328,0.6732,0.136],"r":6.6,"img":"img/E1/walk/p002_21_03.jpg","say":"반성의 대상이에요. 17세기 자연과학자와 사상가들이 만든 '서구의 자연 정복을 통한 자연 지배관' 이에요."},{"b":[0.26,0.47,0.485,0.153],"c":[0.2357,0.454,0.5335,0.185],"r":3.845,"img":"img/E1/walk/p002_21_04.jpg","say":"**자연 지배관(Domination of Nature)** 을 키운 세 가지예요. 물질 무한 이용, **자본주의(Capitalism)** 의 지원, **산업혁명(Industrial Revolution)** 의 효과예요."},{"b":[0.263,0.71,0.653,0.092],"c":[0.2303,0.6834,0.7183,0.1451],"r":6.6005,"img":"img/E1/walk/p002_21_05.jpg","say":"결과가 두 줄이에요. 빈곤으로부터의 해방과 인간, 자연의 생존 위협이 함께 왔고 **전지구적 생태위기(Global Ecological Crisis)** 를 불렀어요."},{"b":[0.121,0.89,0.82,0.034],"c":[0.08,0.8159,0.902,0.1822],"r":6.6008,"img":"img/E1/walk/p002_21_06.jpg","say":"맨 아래 줄이 위기 인식의 시작이에요. **성장의 한계(Limits to Growth)**, **리우환경회의(Rio Conference)**(92년), **교토의정서(Kyoto Protocol)**(97년) 순서예요."}]}},{"p":3,"title":"자연지배관 이전의 토속건축: 지붕이 다른 이유","terms":["Vernacular Architecture","Domination of Nature","Matmata"],"pass1":[{"kind":"say","lines":["앞 쪽에서 **자연 지배관(Domination of Nature)** 을 봤어요. 자연을 정복해도 된다는 생각이었죠.","그 생각이 생기기 전에 사람들은 어떻게 집을 지었을까요?","그 답이 **토속건축(Vernacular Architecture)** 이에요.","한마디로 동네 날씨에 맞춘 집이에요."]},{"kind":"analogy","head":"날씨에 맞춰 옷을 골라 입기","scene":"겨울에는 패딩, 여름에는 반팔을 골라 입어요. 동네 날씨를 보고 옷을 고르는 것과 같아요.","map":[["계절에 맞춰 고른 옷","**토속건축(Vernacular Architecture)**"],["바람 많은 날의 모자 끈","제주도의 낮은 지붕과 지붕을 묶은 줄"],["눈을 털어 내는 우산","핀란드의 가파른 지붕"]]}],"pass2":[{"kind":"points","head":"먼저 용어의 뜻이에요","items":["**토속건축(Vernacular Architecture)**: 그 지역의 바람, 눈, 더위 같은 특성에 맞춰 지은 옛날 집이에요.","슬라이드 말로는 '지역 특성에 맞는 건축 양식' 이에요.","**자연 지배관(Domination of Nature)** 과 정반대예요. 이기려 하지 않고 맞추는 쪽이에요."]},{"kind":"look","walked":1},{"kind":"compare","head":"같은 지붕인데 왜 이렇게 다를까요","cols":["항목","제주도","핀란드"],"rows":[["맞서는 날씨","바람","눈"],["지붕 모양","낮고 둥글어요","가파르고 뾰족해요"],["까닭","높으면 바람에 날아가요","낮으면 눈 무게에 무너져요"],["딸린 장치","돌담, 지붕을 묶은 줄","눈이 미끄러져 내리는 경사"]]},{"kind":"prof","when":"2주차 목요일 수업","lines":["산업혁명 전까지 인류가 하던 건축이 토속건축이고, 자연환경에 순응한 건축이라고 하셨어요.","지붕의 기울기를 물매라고 부른다고 알려 주셨어요.","제주도는 바람이 세서 지붕을 낮게 하고 돌담을 쌓고 지붕을 줄로 묶었대요.","핀란드는 눈이 무거워서 지붕을 뾰족하게 해 눈이 떨어져 나가게 했대요."]}],"pass3":[{"kind":"check","q":"**토속건축(Vernacular Architecture)** 의 뜻으로 맞는 것은?","choices":["지역 특성에 맞는 건축 양식","지역특성과 상관없이 퍼져 간 건축","하중을 받지 않는 바깥벽","빗물을 모아 다시 쓰는 시설"],"a":0,"why":"**토속건축(Vernacular Architecture)** 은 그 지역의 바람, 눈, 더위에 맞춘 옛날 집이에요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"토속건축은 자연지배관 이전의 건축으로, 지역 특성에 맞는 건축 양식이다.","ko":"바람과 눈에 영향을 받은 지붕, 사막지방과 열대지방의 차이가 대표 사례예요.","tip":"'지역 특성에 맞는' 이 여덟 글자만 정확히 외우면 반은 맞아요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["제주도는 바람, 핀란드는 눈이에요. 둘을 바꿔 쓰지 않게 조심해요.","다음 쪽의 **마트마타(Matmata)** 는 사막지방 사례예요. 여기 두 사진과 섞지 마세요."]}],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.063,0.102,0.306,0.038],"c":[0.0477,0.066,0.3366,0.11],"r":4.08,"img":"img/E1/walk/p003_21_01.jpg","say":"소제목이 '자연지배관 역사 (+추가)' 예요. 추가는 교수님이 책머리 내용을 더해 주신 부분이라는 뜻이에요."},{"b":[0.087,0.23,0.675,0.034],"c":[0.0532,0.172,0.7425,0.15],"r":6.6,"img":"img/E1/walk/p003_21_02.jpg","say":"1) 자연지배관 이전의 토속건축, 곧 지역 특성에 맞는 건축 양식이에요."},{"b":[0.117,0.29,0.35,0.032],"c":[0.0995,0.251,0.385,0.11],"r":4.6667,"img":"img/E1/walk/p003_21_03.jpg","say":"첫 번째 포인트: 바람과 눈에 영향을 받은 지붕이에요."},{"b":[0.117,0.35,0.33,0.032],"c":[0.1005,0.311,0.363,0.11],"r":4.4,"img":"img/E1/walk/p003_21_04.jpg","say":"두 번째 포인트: 사막지방과 열대지방의 차이예요. 다음 쪽에서 봐요."},{"b":[0.065,0.47,0.455,0.42],"c":[0.0422,0.449,0.5005,0.462],"r":1.4444,"img":"img/E1/walk/p003_21_05.jpg","say":"왼쪽 사진은 제주도예요. 지붕이 낮고 둥글며 줄로 묶여 있어요."},{"b":[0.545,0.47,0.395,0.42],"c":[0.5252,0.449,0.4345,0.462],"r":1.254,"img":"img/E1/walk/p003_21_06.jpg","say":"오른쪽 사진은 핀란드예요. 지붕이 가파르고 눈이 덮여 있어요."}]}},{"p":4,"title":"사막지방과 열대지방: 똑같이 더운데 집이 반대예요","terms":["Vernacular Architecture","Matmata"],"pass1":[{"kind":"say","lines":["같은 **토속건축(Vernacular Architecture)** 이야기가 이어져요.","이번에는 둘 다 더운 지역인데 집이 정반대예요.","사막지방은 땅속으로 들어가고, 열대지방은 공중으로 띄워요.","더위의 종류가 다르기 때문이에요."]}],"pass2":[{"kind":"points","head":"먼저 용어의 뜻이에요","items":["**마트마타(Matmata)**: 튀니지 사막에 땅을 파서 만든 지하마을이에요.","슬라이드 캡션 그대로 '사막지방 (튀니지 지하마을: 마트마타)' 예요.","**토속건축(Vernacular Architecture)** 의 사막지방 대표 사례로 나와요."]},{"kind":"look","walked":1},{"kind":"compare","head":"더위가 달라서 집도 달라요","cols":["항목","사막지방","열대지방"],"rows":[["괴로운 것","뜨거운 햇빛과 열","더위에 더해진 습기"],["집의 자리","땅 아래로 파고들어요","기둥 위로 띄워요"],["열고 닫기","햇빛과 만나는 면을 최소로 닫아요","창과 문을 다 열어요"],["슬라이드 사례","**마트마타(Matmata)**","기둥 위 누각 형태의 집"]]},{"kind":"prof","when":"2주차 목요일 수업","lines":["사막지방과 열대지방은 똑같이 더운데 모습이 다르다고 하셨어요.","사막은 너무 뜨거워 땅 밑으로 들어갔고, 그것이 튀니지의 지하주택 마트마타래요.","열대는 습해서 지하로 가면 곰팡이가 되니 누각처럼 띄우고 개구부를 다 열어 둔대요.","보기 네 개 중 성격이 다른 하나를 고르는 식으로 문제를 낼 수 있다고 하셨어요."]}],"pass3":[{"kind":"check","q":"**마트마타(Matmata)** 가 있는 곳과 지역 구분이 맞게 짝지어진 것은?","choices":["튀니지, 사막지방","튀니지, 열대지방","핀란드, 한대지방","제주도, 온대지방"],"a":0,"why":"슬라이드 캡션이 '사막지방 (튀니지 지하마을: 마트마타)' 예요."},{"kind":"check","q":"열대지방 토속건축의 특징으로 맞는 것은?","choices":["땅을 파서 햇빛을 모두 차단해요","집을 기둥 위로 띄우고 개구부를 열어 둬요","지붕을 가파르게 해서 눈을 털어요"],"a":1,"why":"열대는 습기가 문제라서 띄우고 열어요. 땅을 파는 것은 사막지방이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["네 사례 중 성격이 다른 하나를 묻는 문제가 나올 수 있어요. 제주도와 핀란드는 지붕, 사막과 열대는 더위예요.","**마트마타(Matmata)** 를 열대지방 사례로 적으면 틀려요. 사막지방이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p004_h.jpg"},"parts":[{"b":[0.087,0.23,0.675,0.034],"c":[0.0532,0.172,0.7425,0.15],"r":6.6,"img":"img/E1/walk/p004_21_01.jpg","say":"제목 줄은 앞 쪽과 같아요. 1) 자연지배관 이전의 토속건축이에요."},{"b":[0.117,0.35,0.33,0.032],"c":[0.1005,0.311,0.363,0.11],"r":4.4,"img":"img/E1/walk/p004_21_02.jpg","say":"이 쪽이 다루는 포인트예요. 사막지방과 열대지방의 차이예요."},{"b":[0.063,0.45,0.44,0.49],"c":[0.041,0.4255,0.484,0.539],"r":1.1973,"img":"img/E1/walk/p004_21_03.jpg","say":"왼쪽 사진과 캡션이에요. 땅을 파 내려간 마당이 보여요. 사막지방 튀니지 지하마을 **마트마타(Matmata)** 예요."},{"b":[0.53,0.45,0.41,0.49],"c":[0.5095,0.4255,0.451,0.539],"r":1.1156,"img":"img/E1/walk/p004_21_04.jpg","say":"오른쪽 사진과 캡션이에요. 기둥 위로 띄운 집이고 옆이 다 열려 있어요. 열대지방이에요."}]}},{"p":5,"title":"산업혁명 이후: 현대건축의 세 가지 특징과 커튼월","terms":["Industrial Revolution","Modern Architecture","Crystal Palace","Internationalism","Curtain Wall"],"pass1":[{"kind":"say","lines":["이제 이야기가 뒤집혀요. **산업혁명(Industrial Revolution)** 이 일어나요.","그 뒤에 나온 건축이 **현대건축(Modern Architecture)** 이에요.","맞추던 집이 이기려는 집으로 바뀌어요.","특징이 딱 세 가지인데 도미노처럼 이어져요."]},{"kind":"figure","head":"도미노처럼 이어지는 세 가지 특징","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"26\" width=\"440\" height=\"46\" rx=\"2\" class=\"box b1\"/><text x=\"240\" y=\"55\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b1\">1) 구조와 재료의 혁명적 발전<\/text><line x1=\"240\" y1=\"74\" x2=\"240\" y2=\"91\" class=\"e2 b2\"/><polygon points=\"240,100 235,91 245,91\" class=\"arrow b2\"/><rect x=\"20\" y=\"102\" width=\"440\" height=\"46\" rx=\"2\" class=\"box b2\"/><text x=\"240\" y=\"131\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b2\">2) 거대공간, 초고층건물 탄생<\/text><line x1=\"240\" y1=\"150\" x2=\"240\" y2=\"167\" class=\"e2 b3\"/><polygon points=\"240,176 235,167 245,167\" class=\"arrow b3\"/><rect x=\"20\" y=\"178\" width=\"440\" height=\"46\" rx=\"2\" class=\"box2 b3\"/><text x=\"240\" y=\"207\" font-size=\"17\" text-anchor=\"middle\" class=\"tb b3\">3) 내부 환경의 인공적 조절<\/text><text x=\"240\" y=\"250\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b3\">앞이 뒤를 불러요. 도미노처럼요.<\/text><\/svg>","caption":"구조와 재료가 좋아지니 거대하고 높아졌고, 그러니 안을 기계로 조절할 수밖에 없어졌어요.","builds":3}],"pass2":[{"kind":"points","head":"먼저 용어의 뜻이에요","items":["**현대건축(Modern Architecture)**: 산업혁명 이후 새 구조와 재료로 생긴 거대하고 높은 건축이에요.","**국제주의(Internationalism)**: 지역 특성과 상관없이 어디서나 똑같이 퍼져 간 건축 경향이에요.","**커튼월(Curtain Wall)**: 건물 무게는 받치지 않고 커튼처럼 공간만 막아 주는 바깥벽이에요."]},{"kind":"look","walked":1},{"kind":"points","head":"**커튼월(Curtain Wall)** 을 한 번 더 풀어 볼게요","items":["가운데 구조체가 건물 무게를 다 받아요.","바깥의 유리는 안과 밖을 가르는 커튼 역할만 해요.","그래서 초고층 건물의 외벽을 시공할 때 이 공법을 써요.","비유로 하면 건물의 피부인데, 뼈대 노릇은 하지 않는 피부예요."]},{"kind":"prof","when":"2주차 목요일 수업","lines":["산업혁명 이후 현대건축의 특징이 셋이라고 하셨어요.","첫째 구조와 재료의 혁명적 발전, 둘째 거대공간과 초고층 건물, 셋째 내부 환경의 인공적 조절이에요.","벽돌로는 120층을 못 짓지만 철근 콘크리트와 유리로는 짓는다고 예를 드셨어요.","초고층에서는 창문을 못 여니 여름엔 덥고 겨울엔 추워졌대요."]},{"kind":"prof","when":"2주차 목요일 수업","lines":["커튼월은 외벽이 건물 하중을 받지 않는 공법이라고 하셨어요.","장점은 밖에서 아름답고 안에서 개방감이 좋은 것이래요.","최대 단점은 1층부터 꼭대기까지 유리라서 단열에 너무 취약한 것이라고 하셨어요.","19세기 중반에는 단열 기술을 더할 생각을 한 사람이 없었대요."]}],"pass3":[{"kind":"check","q":"**현대건축(Modern Architecture)** 의 특징이 아닌 것은?","choices":["구조와 재료의 혁명적 발전","거대공간과 초고층건물 탄생","내부 환경의 인공적 조절","지역 특성에 맞춘 지붕 물매"],"a":3,"why":"지역 특성에 맞춘 것은 **토속건축(Vernacular Architecture)** 이에요. 현대건축은 어디서나 똑같이 퍼졌어요."},{"kind":"check","q":"**커튼월(Curtain Wall)** 을 바르게 설명한 것은?","choices":["건물의 하중을 지지하는 두꺼운 돌벽","건물의 하중은 지지하지 않고 공간을 칸막이하는 바깥벽","지붕 위에 흙을 깔아 만든 정원"],"a":1,"why":"슬라이드 설명 그대로예요. 커튼처럼 공간만 막는 바깥벽이에요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"산업혁명 이후 현대건축의 특징은 구조와 재료의 혁명적 발전, 거대공간과 초고층건물의 탄생, 내부 환경의 인공적 조절이다.","ko":"앞의 두 가지가 세 번째를 불렀다는 순서까지 쓰면 좋아요.","tip":"'구조재료 → 거대초고층 → 인공조절' 도미노로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**커튼월(Curtain Wall)** 는 무게를 받지 '않는' 벽이에요. 받는다고 쓰면 틀려요.","**국제주의(Internationalism)** 는 지역 특성을 따지지 않는다는 뜻이에요. 국제 협약 이름이 아니에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p005_h.jpg"},"parts":[{"b":[0.085,0.23,0.367,0.035],"c":[0.0667,0.1925,0.4037,0.11],"r":4.8933,"img":"img/E1/walk/p005_21_01.jpg","say":"2) 산업혁명 이후 현대건축 발생이라는 제목 줄이에요."},{"b":[0.117,0.29,0.659,0.032],"c":[0.0841,0.2328,0.7249,0.1465],"r":6.5975,"img":"img/E1/walk/p005_21_02.jpg","say":"특징 1. 구조와 재료의 혁명적 발전으로 거대공간과 초고층건물이 탄생했어요."},{"b":[0.117,0.35,0.29,0.032],"c":[0.1025,0.311,0.319,0.11],"r":3.8667,"img":"img/E1/walk/p005_21_03.jpg","say":"특징 2. 내부 환경의 인공적 조절이에요. 기계로 덥히고 식혀요."},{"b":[0.117,0.41,0.72,0.037],"c":[0.081,0.3485,0.792,0.16],"r":6.6,"img":"img/E1/walk/p005_21_04.jpg","say":"대표적 건물이에요. 1851년 런던세계박람회 **수정궁(Crystal Palace)** 이에요."},{"b":[0.3,0.47,0.555,0.092],"c":[0.2722,0.454,0.6105,0.124],"r":6.5645,"img":"img/E1/walk/p005_21_05.jpg","say":"수정궁이 남긴 것 두 줄이에요. 지역특성과 상관없이 퍼져간 **국제주의(Internationalism)**, 그리고 유리 **커튼월(Curtain Wall)** 공법과 무제한 난방기 냉방기 사용이에요."},{"b":[0.015,0.565,0.33,0.1],"c":[0,0.549,0.363,0.132],"r":3.6667,"img":"img/E1/walk/p005_21_06.jpg","say":"왼쪽 아래 작은 글상자가 **커튼월(Curtain Wall)** 설명이에요. 건물의 하중은 지지하지 않고 단순히 공간을 칸막이하는 커튼 역할만 하는 바깥벽이라고 쓰여 있어요."}]}},{"p":6,"title":"수정궁: 1851피트로 설계해 563미터로 완성","terms":["Crystal Palace","Modern Architecture","Internationalism"],"pass1":[{"kind":"say","lines":["**현대건축(Modern Architecture)** 의 대표 건물 **수정궁(Crystal Palace)** 을 크게 봐요."]},{"kind":"figure","head":"수정궁 숫자 카드","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"240\" y=\"32\" font-size=\"17\" text-anchor=\"middle\" class=\"tb\">수정궁 숫자 카드<\/text><rect x=\"24\" y=\"52\" width=\"208\" height=\"44\" rx=\"2\" class=\"box b1\"/><text x=\"128\" y=\"80\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">1851년 런던세계박람회<\/text><rect x=\"248\" y=\"52\" width=\"208\" height=\"44\" rx=\"2\" class=\"box b1\"/><text x=\"352\" y=\"80\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">건축가 조셉 페스톤<\/text><rect x=\"24\" y=\"110\" width=\"208\" height=\"44\" rx=\"2\" class=\"box2 b2\"/><text x=\"128\" y=\"138\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">설계 1851피트<\/text><rect x=\"248\" y=\"110\" width=\"208\" height=\"44\" rx=\"2\" class=\"box2 b2\"/><text x=\"352\" y=\"138\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">완성 563미터<\/text><rect x=\"24\" y=\"168\" width=\"432\" height=\"44\" rx=\"2\" class=\"box b3\"/><text x=\"240\" y=\"196\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">1936년 화재로 사라짐<\/text><text x=\"240\" y=\"240\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b3\">개최 연도와 설계 길이가 똑같이 1851이에요<\/text><\/svg>","caption":"이 쪽에서 외울 숫자는 1851, 563, 1936 세 개예요.","builds":3}],"pass2":[{"kind":"points","head":"먼저 용어의 뜻이에요","items":["**수정궁(Crystal Palace)**: 1851년 런던세계박람회 전시장이에요. 유리와 철로 조립한 건물이에요.","국문 이름이 수정궁이고 영문 이름이 Crystal Palace 예요.","**현대건축(Modern Architecture)** 의 대표적 건물로 슬라이드에 나와요."]},{"kind":"look","walked":1},{"kind":"points","head":"숫자를 하나씩 붙잡아요","items":["1851년: 최초 세계엑스포인 런던대박람회가 열린 해예요.","건축가: 슬라이드 표기로 조셉 페스톤이에요.","1851피트: 개최년도를 기념한 설계 길이예요.","563미터: 실제로 완성된 길이예요."]},{"kind":"steps","head":"피트를 미터로 바꿔 볼게요","given":"1피트 = 0.3048m 로 계산해요. 이 환산값은 슬라이드에 없는 일반 상식이에요.","steps":["설계 길이: 1851 × 0.3048 = 564.1848, 약 564.18m 예요.","완성 길이 563m 와의 차이: 564.18 - 563 = 약 1.18m 예요.","그래서 설계한 길이와 완성된 길이가 거의 같아요.","연도와 길이 숫자가 1851 로 같다는 점만 확실히 기억하면 돼요."],"answer":"설계 1851피트는 약 564.18m, 완성은 563m 예요."},{"kind":"prof","when":"2주차 목요일 수업","lines":["19세기 중반 런던 세계박람회의 시그니처 건물이 크리스탈 팰리스, 국문으로 수정궁이라고 하셨어요.","벽돌과 석조 건물만 보던 유럽에 유리 건물이 갑자기 나타난 충격이었대요.","1851년을 기념해 1851피트로 설계했고 563m로 완성됐다고 짚어 주셨어요.","철과 유리 딱 두 가지 재료만으로 가로 500m가 넘는 건물을 보여 준 것이래요."]}],"pass3":[{"kind":"check","q":"**수정궁(Crystal Palace)** 의 설계 길이와 완성 길이를 바르게 짝지은 것은?","choices":["설계 1851피트, 완성 563미터","설계 563피트, 완성 1851미터","설계 1936피트, 완성 1851미터"],"a":0,"why":"개최년도 1851을 기념해 1851피트로 설계하고 563미터로 완성했어요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"수정궁은 1851년 런던세계박람회 전시장으로, 개최년도를 기념해 1851피트로 설계되어 563미터로 완성되었다.","ko":"건축가는 슬라이드 표기로 조셉 페스톤이에요.","tip":"'1851 두 번, 563 한 번' 으로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["설계자 이름은 강의자료 표기로 '조셉 페스톤' 이에요. 통상 표기는 '조셉 팩스턴(Joseph Paxton)' 이에요.","1851은 연도이자 설계 길이(피트)예요. 미터가 아니에요.","**국제주의(Internationalism)** 를 타고 이 건물의 방식이 전 세계로 퍼졌어요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p006_h.jpg"},"parts":[{"b":[0.087,0.202,0.549,0.037],"c":[0.0595,0.1595,0.6039,0.122],"r":6.6,"img":"img/E1/walk/p006_21_01.jpg","say":"제목 줄이에요. 1851년 런던세계박람회 'Crystal Palace' (수정궁) 이에요."},{"b":[0.104,0.789,0.38,0.043],"c":[0.085,0.7555,0.418,0.11],"r":5.0667,"img":"img/E1/walk/p006_21_02.jpg","say":"그림 속 자막의 첫 줄이에요. 수정궁 Crystal Palace 라고 쓰여 있어요."},{"b":[0.105,0.869,0.803,0.042],"c":[0.0649,0.8008,0.8833,0.1785],"r":6.5979,"img":"img/E1/walk/p006_21_03.jpg","say":"자막 둘째 줄이에요. 1851년 최초 세계엑스포 런던대박람회 전시장, 건축가 조셉 페스톤이에요."},{"b":[0.105,0.918,0.677,0.043],"c":[0.0711,0.8495,0.7447,0.1505],"r":6.5976,"img":"img/E1/walk/p006_21_04.jpg","say":"자막 셋째 줄이에요. 개최년도를 기념해 1851피트 길이로 설계, 563 미터로 완성이에요."}]}},{"p":7,"title":"수정궁 그림: 투명 유리와 철재의 조립식 공법","terms":["Crystal Palace","High-tech Architecture","Internationalism"],"pass1":[{"kind":"say","lines":["이 쪽은 **수정궁(Crystal Palace)** 을 그린 옛 그림 한 장이에요.","그림 안에 글자가 세 줄 적혀 있어요.","이 세 줄이 수정궁을 한 문장으로 말해 줘요.","핵심은 유리와 철, 그리고 조립식이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"세 줄을 이어 읽으면","items":["투명 유리와 철재의 조립식 공법에 의한 초대형 전시장이에요.","그래서 현대 **하이테크 건축(High-tech Architecture)** 의 뿌리라고 불러요.","**하이테크 건축(High-tech Architecture)**: 첨단 재료와 공법을 드러내는 요즘 건축이에요.","**국제주의(Internationalism)** 를 타고 이 방식이 전 세계로 퍼졌어요."]},{"kind":"prof","when":"2주차 목요일 수업","lines":["국제주의는 국가 간 경계와 지역 차이를 허물고 인류에게 유익한 것은 다 같이 쓰자는 생각이라고 하셨어요.","박람회를 보고 온 전 세계가 나도 써야지 하면서 새 기술과 형태가 퍼져 나갔대요.","국제주의가 그것을 부채질했다고 정리해 주셨어요."]}],"pass3":[{"kind":"check","q":"**수정궁(Crystal Palace)** 을 '현대 **하이테크 건축(High-tech Architecture)** 의 뿌리' 라고 부르는 까닭은?","choices":["투명 유리와 철재의 조립식 공법으로 지은 초대형 전시장이라서","흙과 나무로 지은 지역 재료 건축이라서","지붕에 정원을 올린 최초의 건물이라서"],"a":0,"why":"그림 속 세 줄이 그대로 답이에요. 유리와 철, 조립식, 초대형 전시장이에요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p007_h.jpg"},"parts":[{"b":[0.087,0.179,0.548,0.065],"c":[0.0596,0.1506,0.6028,0.1218],"r":6.5988,"img":"img/E1/walk/p007_20_01.jpg","say":"제목 줄이에요. 1851년 런던세계박람회 'Crystal Palace' (수정궁) 이에요."},{"b":[0.4,0.3,0.54,0.075],"c":[0.373,0.2775,0.594,0.12],"r":6.6,"img":"img/E1/walk/p007_20_02.jpg","say":"그림 속 첫 줄이에요. 투명 유리와 철재의 조립식 공법에 의한 이라고 쓰여 있어요."},{"b":[0.52,0.375,0.42,0.07],"c":[0.499,0.355,0.462,0.11],"r":5.6,"img":"img/E1/walk/p007_20_03.jpg","say":"둘째 줄이에요. 초대형 전시장으로 라고 이어져요."},{"b":[0.56,0.435,0.38,0.075],"c":[0.541,0.4175,0.418,0.11],"r":5.0667,"img":"img/E1/walk/p007_20_04.jpg","say":"셋째 줄이에요. 현대 하이테크 건축의 뿌리라고 맺어요."}]}},{"p":8,"title":"수정궁 내부: 산업디자인이 태동한 곳","terms":["Crystal Palace","Modern Architecture"],"pass1":[{"kind":"say","lines":["**수정궁(Crystal Palace)** 의 내부를 그린 그림이에요.","왼쪽에 글자가 두 덩어리 적혀 있어요.","수정궁이 남긴 것이 나쁜 것만은 아니라는 이야기예요.","디자인의 역사가 여기서 시작돼요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"수정궁이 남긴 좋은 쪽","items":["최초의 국제행사장인 **수정궁(Crystal Palace)** 에서 산업디자인이 태동했어요.","이후 모더니즘, 미니멀리즘 등 현대디자인의 모체가 됐어요.","**현대건축(Modern Architecture)** 이 나쁜 결과만 남긴 것은 아니라는 점을 여기서 짚어요."]},{"kind":"prof","when":"2주차 목요일 수업","lines":["수정궁에 나쁜 것만 있는 것은 아니라고 하셨어요.","산업디자인의 시작, 미니멀리즘, 현대 디자인이라고 하는 지금 우리 사물과 도구들의 시작점이 이 세계박람회래요.","디자인사와 미술사에서도 의의가 깊다고 하셨어요."]}],"pass3":[{"kind":"check","q":"슬라이드가 말하는 **수정궁(Crystal Palace)** 의 디자인사 의의는?","choices":["산업디자인이 태동하고 현대디자인의 모체가 됐어요","토속건축의 지붕 모양을 처음 정리했어요","빗물 저장 시설을 처음 갖췄어요"],"a":0,"why":"왼쪽 글자 그대로예요. 산업디자인 태동, 이후 모더니즘과 미니멀리즘 등 현대디자인의 모체예요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p008_h.jpg"},"parts":[{"b":[0.087,0.202,0.549,0.037],"c":[0.0595,0.1595,0.6039,0.122],"r":6.6,"img":"img/E1/walk/p008_20_01.jpg","say":"제목 줄은 앞 쪽과 같아요. 1851년 런던세계박람회 수정궁이에요."},{"b":[0.045,0.54,0.26,0.12],"c":[0.032,0.524,0.286,0.152],"r":2.5088,"img":"img/E1/walk/p008_20_02.jpg","say":"첫 덩어리예요. 최초로 국제행사장인 수정궁에서 산업디자인 태동 이라고 쓰여 있어요."},{"b":[0.04,0.685,0.26,0.13],"c":[0.027,0.669,0.286,0.162],"r":2.3539,"img":"img/E1/walk/p008_20_03.jpg","say":"둘째 덩어리예요. 이후 모더니즘, 미니멀리즘 등 현대디자인의 모체 라고 이어져요."},{"b":[0.31,0.17,0.66,0.78],"c":[0.274,0.131,0.726,0.858],"r":1.1282,"img":"img/E1/walk/p008_20_04.jpg","say":"오른쪽 그림이에요. 철과 유리로 만든 커다란 아치 아래 만국기와 전시대가 보여요."}]}},{"p":9,"title":"수정궁 전경 사진: 유리 지붕이 이어진 긴 건물","terms":["Crystal Palace"],"pass1":[{"kind":"say","lines":["**수정궁(Crystal Palace)** 사진 쪽이에요.","멀리서 찍은 옛 사진이에요. 둥근 유리 지붕이 길게 이어져요.","이 사진에서 볼 것은 길이예요. 563미터가 얼마나 긴지 느껴 봐요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["내부에도 철제와 유리가 그대로 드러난다고 하셨어요.","벽돌 건물과 석조 건물만 보던 사람들에게는 건물이 이렇게 만들어진다는 것 자체가 충격이었대요.","해상도가 낮은 사진들은 그때 찍힌 실제 사진이라고 알려 주셨어요."]}],"pass3":[],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.063,0.102,0.202,0.035],"c":[0.051,0.0645,0.226,0.11],"r":2.7394,"img":"img/E1/walk/p009_20_01.jpg","say":"소제목만 있는 쪽이에요. 자연지배관 역사 안의 수정궁 이야기가 이어져요."},{"b":[0.045,0.18,0.91,0.76],"c":[0.0,0.142,1,0.836],"r":1.5949,"img":"img/E1/walk/p009_20_02.jpg","say":"사진 전체예요. 좌우로 아주 긴 몸체와 가운데의 둥근 유리 지붕, 양쪽 끝의 급수탑이 보여요."}]}},{"p":10,"title":"수정궁 외관 사진: 아치 끝에서 본 모습","terms":["Crystal Palace"],"pass1":[{"kind":"say","lines":["**수정궁(Crystal Palace)** 사진 쪽이에요.","건물의 짧은 쪽 끝에서 올려다본 사진이에요.","바깥벽이 거의 다 유리라는 점을 눈으로 확인해요."]}],"pass2":[{"kind":"look","walked":1}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p010_h.jpg"},"parts":[{"b":[0.087,0.202,0.549,0.037],"c":[0.0595,0.1595,0.6039,0.122],"r":6.6,"img":"img/E1/walk/p010_20_01.jpg","say":"제목 줄이에요. 1851년 런던세계박람회 수정궁이에요."},{"b":[0.12,0.29,0.76,0.65],"c":[0.082,0.2575,0.836,0.715],"r":1.559,"img":"img/E1/walk/p010_20_02.jpg","say":"사진 전체예요. 커다란 반원 아치와 층층이 쌓인 유리벽이 보여요. 바깥벽이 거의 다 유리예요."}]}},{"p":11,"title":"수정궁 내부 공사 사진 두 장","terms":["Crystal Palace"],"pass1":[{"kind":"say","lines":["**수정궁(Crystal Palace)** 사진 쪽이에요.","공사 중과 전시 준비 중의 내부를 찍은 사진 두 장이에요.","철 뼈대가 그대로 보이는 점이 이 시대에는 놀라운 일이었어요."]}],"pass2":[{"kind":"look","walked":1}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p011_h.jpg"},"parts":[{"b":[0.087,0.202,0.549,0.037],"c":[0.0595,0.1595,0.6039,0.122],"r":6.6,"img":"img/E1/walk/p011_20_01.jpg","say":"제목 줄이에요. 1851년 런던세계박람회 수정궁이에요."},{"b":[0.05,0.27,0.44,0.7],"c":[0.028,0.23,0.484,0.77],"r":0.8381,"img":"img/E1/walk/p011_20_02.jpg","say":"왼쪽 사진이에요. 커다란 석상 뒤로 아치형 유리 지붕의 뼈대가 보여요."},{"b":[0.52,0.27,0.44,0.63],"c":[0.498,0.2385,0.484,0.693],"r":0.9312,"img":"img/E1/walk/p011_20_03.jpg","say":"오른쪽 사진이에요. 철 기둥과 나선 계단, 아치 뼈대만 드러나 있어요."}]}},{"p":12,"title":"수정궁 내부 사진 두 장: 사람과 함께","terms":["Crystal Palace"],"pass1":[{"kind":"say","lines":["**수정궁(Crystal Palace)** 사진 쪽이에요.","당시 사람들이 앉아 있는 내부 사진 두 장이에요.","사람 크기와 견주어 보면 이 공간이 얼마나 거대한지 알 수 있어요."]}],"pass2":[{"kind":"look","walked":1}],"pass3":[],"pass4":[],"walk":{"head":null,"parts":[{"b":[0.086,0.059,0.202,0.054],"c":[0.074,0.031,0.226,0.11],"r":2.7394,"img":"img/E1/walk/p012_20_01.jpg","say":"소제목이에요. 자연지배관 역사 이야기가 이어져요."},{"b":[0.06,0.15,0.44,0.82],"c":[0.038,0.098,0.484,0.902],"r":0.7154,"img":"img/E1/walk/p012_20_02.jpg","say":"왼쪽 사진이에요. 긴 통로 양쪽에 화분과 조각이 놓였고 아래에 사람들이 앉아 있어요."},{"b":[0.52,0.15,0.44,0.82],"c":[0.498,0.098,0.484,0.902],"r":0.7154,"img":"img/E1/walk/p012_20_03.jpg","say":"오른쪽 사진이에요. 가운데 분수와 식물이 있고 철과 유리 아치가 하늘처럼 덮고 있어요."}]}},{"p":13,"title":"1936년 화재: 수정궁은 남아 있지 않아요","terms":["Crystal Palace"],"pass1":[{"kind":"say","lines":["**수정궁(Crystal Palace)** 의 마지막 이야기예요.","1936년에 불이 나서 다 타 버렸어요.","그래서 지금 런던에 가도 이 건물은 볼 수 없어요.","남은 것은 그림과 옛 사진뿐이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["1936년에 다 탔다고 하셨어요.","유리라서 오래 걸리지도 않고 확 타고 끝났대요.","런던에서 복구를 안 해서 지금은 남아 있지 않고 그림 자료만 남아 있다고 하셨어요."]}],"pass3":[{"kind":"check","q":"**수정궁(Crystal Palace)** 은 지금 어떤 상태일까요?","choices":["1936년 화재로 소실되어 남아 있지 않아요","지금도 런던에서 볼 수 있어요","다른 나라로 옮겨 세웠어요"],"a":0,"why":"1936년 화재로 전소됐고 복구하지 않았어요. 그림과 옛 사진만 남았어요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p013_h.jpg"},"parts":[{"b":[0.103,0.224,0.719,0.037],"c":[0.067,0.1626,0.7909,0.1598],"r":6.5991,"img":"img/E1/walk/p013_20_01.jpg","say":"제목 줄에 화재가 더해졌어요. 1851년 런던세계박람회 수정궁, 1936년 화재예요."},{"b":[0.15,0.3,0.7,0.66],"c":[0.115,0.267,0.77,0.726],"r":1.4141,"img":"img/E1/walk/p013_20_02.jpg","say":"사진이에요. 유리가 모두 사라지고 철 뼈대만 남아 연기가 오르고 있어요."}]}},{"p":14,"title":"오늘의 커튼월 건물: 수정궁의 후손","terms":["Crystal Palace","Curtain Wall","Modern Architecture"],"pass1":[{"kind":"say","lines":["화재 쪽에 이어 오늘날의 초고층 건물 사진이 나와요.","**커튼월(Curtain Wall)** 공법으로 지은 우리 시대의 건물이에요.","**수정궁(Crystal Palace)** 이 보여 준 방식이 여기까지 이어졌어요.","겉이 온통 유리라는 점이 똑같아요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"points","head":"무엇이 같고 무엇이 다를까요","items":["같은 점: 바깥벽이 거의 다 유리인 **커튼월(Curtain Wall)** 이에요.","다른 점: 지금은 단열을 돕는 여러 기술이 함께 들어가 있어요.","**현대건축(Modern Architecture)** 의 흐름이 끝나지 않고 지금까지 이어진다는 뜻이에요."]},{"kind":"prof","when":"2주차 목요일 수업","lines":["지금 우리 시대 커튼월 공법의 정수도 보여 준다고 하셨어요.","수정궁 때와 달리 지금은 단점을 뒷받침하는 신기술이 많이 들어가 있대요.","그 차이를 앞으로 수업에서 몇 가지씩 보게 된다고 하셨어요."]}],"pass3":[{"kind":"check","q":"오늘의 초고층 **커튼월(Curtain Wall)** 건물이 수정궁과 다른 점은?","choices":["단열을 돕는 신기술이 함께 들어가 있어요","유리를 전혀 쓰지 않아요","하중을 외벽이 모두 받아요"],"a":0,"why":"겉은 비슷하지만 지금은 단열에 취약한 점을 보완하는 기술이 들어가 있어요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p014_h.jpg"},"parts":[{"b":[0.098,0.213,0.72,0.052],"c":[0.062,0.159,0.792,0.16],"r":6.6,"img":"img/E1/walk/p014_20_01.jpg","say":"제목 줄은 앞 쪽과 같아요. 수정궁과 1936년 화재예요."},{"b":[0.005,0.33,0.41,0.61],"c":[0,0.2995,0.451,0.671],"r":0.8962,"img":"img/E1/walk/p014_20_02.jpg","say":"왼쪽 사진이에요. 낮에 본 초고층 건물이고 외벽이 전부 유리예요."},{"b":[0.415,0.33,0.58,0.61],"c":[0.362,0.2995,0.638,0.671],"r":1.2678,"img":"img/E1/walk/p014_20_03.jpg","say":"오른쪽 사진이에요. 같은 건물의 저녁 모습이에요. 옆에 호수와 공원이 보여요."}]}},{"p":15,"title":"최고의 풍요시대: 유한함을 몰랐어요","terms":["Modern Architecture","Finiteness","Industrial Revolution"],"pass1":[{"kind":"say","lines":["**현대건축(Modern Architecture)** 이 커지자 에너지가 많이 필요해졌어요.","냉난방기를 돌리려고 석유를 무한정 캐서 썼어요.","사람들은 이것을 역사 이래 최고의 풍요시대라고 스스로 평가했어요.","딱 하나를 몰랐어요. 석유의 **유한함(Finiteness)** 이에요."]}],"pass2":[{"kind":"points","head":"먼저 용어의 뜻이에요","items":["**유한함(Finiteness)**: 언젠가는 바닥난다는 성질이에요.","슬라이드는 이것을 인지하지 못했다고 적어요.","**산업혁명(Industrial Revolution)** 이후 커진 에너지 씀씀이가 배경이에요."]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["산업혁명 이후 현대건축을 지으면서 석탄과 석유로 전기를 만들고 증기기관을 돌렸다고 하셨어요.","기술이 있으니 무한정 캐내면 된다고 생각했대요.","유한하다는 생각을 단 한 명도 하지 않았다고 하셨어요."]}],"pass3":[{"kind":"check","q":"이 쪽이 말하는 풍요시대의 문제는 무엇일까요?","choices":["석유의 유한함을 인지하지 못한 것","지붕 물매를 잘못 잡은 것","지역 재료를 너무 많이 쓴 것"],"a":0,"why":"슬라이드 마지막 줄이 그대로 답이에요. **유한함(Finiteness)** 을 인지하지 못했어요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"산업혁명 이후 냉난방기 사용을 위해 석유에너지를 무한정 채굴하고 사용하면서, 소비가 미덕인 최고의 풍요시대라고 자평했으나 석유의 유한함은 인지하지 못했다.","ko":"무한정 채굴, 소비가 미덕, 유한함 미인지 세 가지가 뼈대예요.","tip":"'무한정 - 미덕 - 몰랐다' 세 박자로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'소비가 미덕' 은 비판하려고 옮겨 적은 그 시대의 구호예요. 이 강의의 주장이 아니에요.","이 쪽까지가 풍요시대예요. 다음 쪽에서 **오일쇼크(Oil Shock)** 로 깨져요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p015_h.jpg"},"parts":[{"b":[0.085,0.23,0.367,0.035],"c":[0.0667,0.1925,0.4037,0.11],"r":4.8933,"img":"img/E1/walk/p015_21_01.jpg","say":"제목 줄이에요. 2) 산업혁명 이후 현대건축 발생이 이어져요."},{"b":[0.112,0.29,0.632,0.032],"c":[0.0804,0.2358,0.6952,0.1405],"r":6.5974,"img":"img/E1/walk/p015_21_02.jpg","say":"냉난방기 사용을 위한 석유에너지 무한정 채굴 및 사용이에요."},{"b":[0.113,0.35,0.555,0.032],"c":[0.0852,0.3043,0.6105,0.1233],"r":6.6018,"img":"img/E1/walk/p015_21_03.jpg","say":"자평 줄이에요. 인류가 성취한 역사 이래 최고의 풍요시대라고 스스로 말했어요."},{"b":[0.218,0.41,0.15,0.032],"c":[0.193,0.371,0.2,0.11],"r":2.4242,"img":"img/E1/walk/p015_21_04.jpg","say":"그 시대의 구호예요. 소비가 미덕이에요."},{"b":[0.117,0.53,0.29,0.032],"c":[0.1025,0.491,0.319,0.11],"r":3.8667,"img":"img/E1/walk/p015_21_05.jpg","say":"결론 줄이에요. 유한함을 인지하지 못했어요."}]}},{"p":16,"title":"1차 오일쇼크: 석유가 무기가 된 날","terms":["Oil Shock","OPEC","Production Cut","Finiteness","Crystal Palace"],"pass1":[{"kind":"say","lines":["풍요시대가 끝나는 쪽이에요.","1973년에 1차 **오일쇼크(Oil Shock)** 가 터져요.","석유가 처음으로 정치적 무기가 됐어요.","이때 사람들이 처음으로 석유의 **유한함(Finiteness)** 을 느껴요."]},{"kind":"figure","head":"수정궁에서 오일쇼크까지","svg":"<svg viewBox=\"0 0 480 270\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"30\" y1=\"150\" x2=\"450\" y2=\"150\" class=\"e\"/><circle cx=\"90\" cy=\"150\" r=\"11\" class=\"n2 b1\"/><text x=\"90\" y=\"122\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b1\">1851년<\/text><text x=\"90\" y=\"184\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b1\">수정궁<\/text><circle cx=\"270\" cy=\"150\" r=\"11\" class=\"n2 b2\"/><text x=\"270\" y=\"122\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">1973년<\/text><text x=\"270\" y=\"184\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b2\">1차 오일쇼크<\/text><circle cx=\"410\" cy=\"150\" r=\"11\" class=\"n b3\"/><text x=\"410\" y=\"122\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">1978년<\/text><text x=\"410\" y=\"184\" font-size=\"14\" text-anchor=\"middle\" class=\"tm b3\">2차 오일쇼크<\/text><text x=\"180\" y=\"216\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b2\">약 120년<\/text><text x=\"240\" y=\"246\" font-size=\"15\" text-anchor=\"middle\" class=\"tm b3\">풍요시대가 끝나고 유한함을 알게 돼요<\/text><\/svg>","caption":"**수정궁(Crystal Palace)**(1851) 에서 1차 **오일쇼크(Oil Shock)**(1973) 까지 약 120년이에요.","builds":3}],"pass2":[{"kind":"points","head":"먼저 용어의 뜻이에요","items":["**오일쇼크(Oil Shock)**: 석유 값이 갑자기 크게 뛰어 세계가 흔들린 사건이에요.","**석유수출국기구(OPEC)**: 석유를 수출하는 나라들의 모임이에요. 한국어로 석유수출국기구예요.","**감산(Production Cut)**: 만드는 양을 줄이는 것이에요. 슬라이드는 축소라고 덧붙여요."]},{"kind":"look","walked":1},{"kind":"steps","head":"매월 전월에 비해 5%씩 줄이면 얼마가 남을까요","given":"처음 생산량을 100% 로 두고 매달 0.95 를 곱해요.","steps":["1개월 뒤: 100 × 0.95 = 95%","2개월 뒤: 95 × 0.95 = 90.25%","3개월 뒤: 90.25 × 0.95 = 약 85.74%","6개월 뒤: 약 73.51%","함정: 5 × 6 = 30 을 빼서 70% 라고 하면 틀려요. 차이가 약 3.51%p 예요."],"answer":"6개월 뒤 약 73.51% 가 남아요. 빼기가 아니라 곱하기예요."},{"kind":"prof","when":"2주차 목요일 수업","lines":["세계사 수업이 아니니 1차 오일쇼크가 있었다는 것만 기억하면 된다고 하셨어요.","중동에서 전쟁이 났고 석유를 정치적 무기로 쓰겠다고 처음으로 대놓고 말했대요.","이스라엘이 철수하지 않으면 생산량을 줄이겠다고 협박했고 1년 만에 기름값이 4배 올랐어요.","돈이 있어도 석유를 못 사는 일을 전 세계가 처음 겪었다고 하셨어요."]},{"kind":"prof","when":"2주차 목요일 수업","lines":["석유가 언젠가 없어질 수 있다는 것을 느낀 때를 짚어 주셨어요.","런던박람회 이후 약 120년이 지난 1973년이래요.","그래서 슬라이드 제목에도 '런던박람회 후 약 120년' 이라고 적혀 있어요."]}],"pass3":[{"kind":"check","q":"1차 **오일쇼크(Oil Shock)** 때 **석유수출국기구(OPEC)** 가 발표한 원유 가격 인상률은?","choices":["17%","5%","4배","120%"],"a":0,"why":"6개 석유수출국이 **석유수출국기구(OPEC)** 회의에서 원유 가격 17% 인상을 발표했어요. 5% 는 매월 **감산(Production Cut)** 비율이에요."},{"kind":"check","q":"1차 **오일쇼크(Oil Shock)** 의 직접적인 계기가 된 사건은?","choices":["1973년 이집트와 시리아의 이스라엘 침공(4차 중동 전쟁)","1978년 이란의 쿠데타와 파업","1851년 런던세계박람회"],"a":0,"why":"1973년 10월 6일 4차 중동 전쟁이 1차 오일쇼크의 시작이에요. 이란 쿠데타는 2차예요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"1차 오일쇼크는 1973년 4차 중동 전쟁을 계기로 석유수출국기구가 원유 가격 17% 인상과 매월 전월 대비 5% 감산을 결정하면서 일어났고, 중동산 원유 가격이 1년 만에 4배 가까이 올랐다.","ko":"17%, 5%, 4배 세 숫자가 답안의 뼈대예요.","tip":"'십칠, 오, 네 배' 를 순서대로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["17% 는 가격 인상률, 5% 는 매월 **감산(Production Cut)** 비율, 4배는 1년 뒤 가격이에요. 자리를 바꾸면 틀려요.","1차는 1973년 중동 전쟁, 2차는 1978년 이란 쿠데타예요.","매월 5%씩 줄이는 것은 곱하기라서 6개월 뒤가 70%가 아니라 약 73.51% 예요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p016_h.jpg"},"parts":[{"b":[0.085,0.23,0.661,0.034],"c":[0.0519,0.1736,0.7271,0.1469],"r":6.5995,"img":"img/E1/walk/p016_21_01.jpg","say":"제목 줄이에요. 3) 런던박람회 후 약 120년, 1차 오일쇼크예요."},{"b":[0.117,0.29,0.781,0.033],"c":[0.078,0.2197,0.8591,0.1736],"r":6.5983,"img":"img/E1/walk/p016_21_02.jpg","say":"1973년 10월 6일, 이집트와 시리아가 이스라엘을 침공한 4차 중동 전쟁이에요."},{"b":[0.138,0.35,0.749,0.092],"c":[0.1005,0.3128,0.8239,0.1665],"r":6.5978,"img":"img/E1/walk/p016_21_03.jpg","say":"열흘 후 6개 석유수출국이 **석유수출국기구(OPEC)** 회의에서 원유 가격 17% 인상을 발표했어요. 석유를 정치적 무기로 쓰겠다는 선언이에요."},{"b":[0.117,0.47,0.808,0.092],"c":[0.0766,0.4262,0.8888,0.1796],"r":6.5984,"img":"img/E1/walk/p016_21_04.jpg","say":"조건이에요. 이스라엘이 아랍 점령지역에서 철수하지 않으면 매월 원유생산을 전월에 비해 5% 씩 **감산(Production Cut)** 하겠다고 결정했어요."},{"b":[0.117,0.59,0.479,0.032],"c":[0.0931,0.551,0.5269,0.11],"r":6.3867,"img":"img/E1/walk/p016_21_05.jpg","say":"결과 줄이에요. 중동산 원유 값이 1년 만에 4배 가까이 올랐어요."},{"b":[0.12,0.71,0.607,0.032],"c":[0.0897,0.6586,0.6677,0.1349],"r":6.5995,"img":"img/E1/walk/p016_21_06.jpg","say":"맺음 줄이에요. 처음으로 석유가 무한정하지 않음을 인지하기 시작했어요."}]}},{"p":17,"title":"2차 오일쇼크: 1978년 이란 쿠데타","terms":["Oil Shock","Alternative Energy"],"pass1":[{"kind":"say","lines":["석유 때문에 세계가 흔들린 일이 5년 만에 또 일어났어요.","1978년 2차 **오일쇼크(Oil Shock)** 이야기예요.","이번 시작은 전쟁이 아니라 이란에서 일어난 쿠데타였어요.","석유가 모자라니 값이 치솟고 세계 경제가 오래 휘청였어요."]}],"pass2":[{"kind":"points","head":"용어 먼저: **오일쇼크(Oil Shock)** 와 **대체에너지(Alternative Energy)**","items":["**오일쇼크(Oil Shock)** 은 석유 값이 갑자기 크게 뛰어 세계가 흔들린 사건이에요.","1973년이 1차, 1978년이 2차예요.","**대체에너지(Alternative Energy)** 는 석유 대신 쓸 에너지예요."]},{"kind":"points","head":"4) 2차 **오일쇼크(Oil Shock)** 네 줄","items":["1978년 이란에서 쿠데타가 발생했어요.","이란의 유전 노동자들이 국왕에 대항해 파업에 돌입했어요.","급격한 이란의 석유수출 감소에 의해 석유 가격이 폭등했어요.","1980년대 초까지 안정되지 않는 석유가격에 의해 세계경제 혼란이 지속됐어요."]},{"kind":"points","head":"슬라이드 마지막 두 줄","items":["1차 2차 석유파동에 의한 석유자원의 고갈 위협 등을 겪으면서,","비로소 **대체에너지(Alternative Energy)** 개발에 관심을 갖기 시작했어요.","'처음으로' 가 아니라 '비로소' 예요. 두 번을 맞고 나서라는 뜻이에요."]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["2차 오일쇼크는 5년 만에 또 터졌다고 하셨어요.","이번에는 이란에서 유전 노동자들이 쿠데타를 일으켜 파업한 것이 원인이에요.","이란이 석유를 못 만드니 석유량 자체가 급감하고 가격이 폭등했어요.","80년대 초까지 세계 경제가 흔들렸다고 하셨어요."]}],"pass3":[{"kind":"check","q":"2차 **오일쇼크(Oil Shock)** 의 원인으로 맞는 것은?","choices":["이집트와 시리아가 이스라엘을 침공한 전쟁","이란의 쿠데타와 유전 노동자 파업","미국의 LEED 평가기준 마련","1992년 리우환경회의 개최"],"a":1,"why":"2차 **오일쇼크(Oil Shock)** 은 1978년 이란의 쿠데타와 유전 노동자 파업에서 시작했어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["1차는 1973년 중동 전쟁, 2차는 1978년 이란이에요. 나라를 바꾸면 틀려요.","2차 뒤에 '비로소' **대체에너지(Alternative Energy)** 에 관심을 가졌어요. 1차 뒤가 아니에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p017_h.jpg"},"parts":[{"b":[0.08,0.225,0.38,0.042],"c":[0.061,0.191,0.418,0.11],"r":5.0667,"img":"img/E1/walk/p017_23_01.jpg","say":"제목 줄이에요. 2차 **오일쇼크(Oil Shock)** 이야기예요."},{"b":[0.11,0.285,0.36,0.042],"c":[0.092,0.251,0.396,0.11],"r":4.8,"img":"img/E1/walk/p017_23_02.jpg","say":"원인이에요. 1978년 이란에서 쿠데타가 발생했어요."},{"b":[0.11,0.345,0.6,0.042],"c":[0.08,0.2993,0.66,0.1333],"r":6.6017,"img":"img/E1/walk/p017_23_03.jpg","say":"유전 노동자들이 국왕에 대항해 파업에 돌입했어요."},{"b":[0.11,0.405,0.62,0.042],"c":[0.079,0.3571,0.682,0.1378],"r":6.5989,"img":"img/E1/walk/p017_23_04.jpg","say":"석유수출이 급격히 줄어 석유 가격이 폭등했어요."},{"b":[0.11,0.465,0.8,0.042],"c":[0.07,0.3971,0.88,0.1778],"r":6.5992,"img":"img/E1/walk/p017_23_05.jpg","say":"1980년대 초까지 세계경제 혼란이 이어졌어요."},{"b":[0.11,0.585,0.8,0.105],"c":[0.07,0.5486,0.88,0.1778],"r":6.5992,"img":"img/E1/walk/p017_23_06.jpg","say":"결론 두 줄이에요. 비로소 **대체에너지(Alternative Energy)** 개발에 관심을 가졌어요."}]}},{"p":18,"title":"석유위기 이후: 나라마다 만든 건물 성적표","terms":["Rating System","BREEAM","LEED","G-SEED","Sustainable Future","Modern Architecture","Rio Conference","Alternative Energy"],"pass1":[{"kind":"say","lines":["두 번의 석유 위기를 겪은 뒤 세계가 건축을 돌아봤어요.","그리고 나라마다 건물의 성적표, **등급 평가기준(Rating System)** 을 만들었어요.","영국 **브리암(BREEAM)**, 미국 **LEED**, 한국 **녹색건축인증(G-SEED)** 세 개만은 꼭 외워요."]}],"pass2":[{"kind":"points","head":"용어 먼저: **등급 평가기준(Rating System)**","items":["**등급 평가기준(Rating System)** 은 건물이 얼마나 친환경인지 점수와 등급을 매기는 기준이에요.","건물의 성적표라고 생각하면 쉬워요.","이름이 모두 줄임말이라 대문자로 써요."]},{"kind":"points","head":"5) 석유위기 이후 두 줄","items":["**현대건축(Modern Architecture)** 과 도시 상태를 돌아보기 시작했어요.","에너지 절감을 바탕으로 한 친환경설계가 시작됐어요.","앞 쪽에서 본 **대체에너지(Alternative Energy)** 개발 관심이 여기로 이어져요."]},{"kind":"compare","head":"나라별 **등급 평가기준(Rating System)**","cols":["나라","연도","이름"],"rows":[["영국","1990년대부터","**브리암(BREEAM)** 건축환경등급 평가기준, 요소기술 개발과 가이드북 보급"],["캐나다","1993년","C-2000 Program 등급 평가기준"],["미국","1993년","USDBC 설립 및 **LEED** 친환경건축물등급 평가기준"],["일본, 프랑스, 독일","표기 없음","기술 개발 및 보급"],["한국","2002년","친환경건축물 인증제도 시행, 현 **녹색건축인증(G-SEED)**"]]},{"kind":"points","head":"맨 아래 두 줄","items":["1992년 **리우환경회의(Rio Conference)** 의 1993년 환경선언이 내건 말이 **지속가능한 미래(Sustainable Future)** 예요.","우리 세대뿐 아니라 다음 세대까지 쓸 수 있는 지구를 뜻해요.","슬라이드 맨 아래에는 '현 시대에는 기후위기' 라고 덧붙여져 있어요."]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["두 번을 맞고 나서 석유와 거리를 둬야겠다고 한 것이 사실상 대체에너지의 시작점이래요.","산업혁명을 먼저 한 영국에서 친환경 설계 가이드북도 처음 나왔다고 하셨어요.","볼드체로 해 둔 BREEAM(브리암), LEED(리드), G-SEED 세 개만은 외우자고 하셨어요.","인증 제도 이름은 다 줄임말이라 반드시 대문자로 쓰라고 하셨어요."]}],"pass3":[{"kind":"check","q":"나라와 **등급 평가기준(Rating System)** 의 연결로 옳지 않은 것은?","choices":["영국, BREEAM 건축환경등급 평가기준","캐나다, 1993년 C-2000 Program","미국, 1993년 LEED","한국, 1993년 친환경건축물 인증제도"],"a":3,"why":"한국은 2002년에 시행했고 지금 이름은 **녹색건축인증(G-SEED)** 예요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"영국은 BREEAM, 미국은 LEED, 한국은 2002년 시행한 G-SEED 를 마련했다.","ko":"세 나라의 **등급 평가기준(Rating System)** 이름을 대문자 그대로 쓰는 것이 핵심이에요.","tip":"영미한 순서로 브리암, 리드, 지시드 라고 소리 내어 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드 표기는 'USDBC' 예요. 통상 표기는 'USGBC' 예요. 시험에는 슬라이드 표기를 따라요.","캐나다 C-2000 과 미국 **LEED** 는 둘 다 1993년이에요.","1993년 환경선언의 말은 **지속가능한 미래(Sustainable Future)** 예요. 평가기준 이름이 아니에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p018_h.jpg"},"parts":[{"b":[0.08,0.225,0.2,0.042],"c":[0.068,0.191,0.224,0.11],"r":2.7152,"img":"img/E1/walk/p018_24_01.jpg","say":"제목이에요. 5) 석유위기 이후예요."},{"b":[0.14,0.285,0.51,0.105],"c":[0.1145,0.269,0.561,0.137],"r":5.4599,"img":"img/E1/walk/p018_24_02.jpg","say":"**현대건축(Modern Architecture)** 과 도시를 돌아보고 에너지 절감 친환경설계가 시작돼요."},{"b":[0.14,0.405,0.82,0.105],"c":[0.098,0.3664,0.902,0.1822],"r":6.6008,"img":"img/E1/walk/p018_24_03.jpg","say":"영국 줄이에요. **브리암(BREEAM)** 건축환경등급 평가기준이에요."},{"b":[0.14,0.525,0.82,0.105],"c":[0.098,0.4864,0.902,0.1822],"r":6.6008,"img":"img/E1/walk/p018_24_04.jpg","say":"캐나다 C-2000(1993), 미국 USDBC 와 **LEED**(1993) 예요."},{"b":[0.14,0.705,0.79,0.042],"c":[0.1005,0.6382,0.869,0.1756],"r":6.5983,"img":"img/E1/walk/p018_24_05.jpg","say":"한국은 2002년 시행, 지금 이름이 **녹색건축인증(G-SEED)** 예요."},{"b":[0.14,0.765,0.81,0.042],"c":[0.0995,0.696,0.891,0.18],"r":6.6,"img":"img/E1/walk/p018_24_06.jpg","say":"1992년 **리우환경회의(Rio Conference)**, 1993년 환경선언은 **지속가능한 미래(Sustainable Future)** 예요."}]}},{"p":19,"title":"친환경건축의 개념: 생태질서 회복과 생태주의","terms":["Climate Change Convention","Ecological Order Restoration","Biotop","Ecology","Ecologism","Rio Conference","Kyoto Protocol","Alternative Energy"],"pass1":[{"kind":"say","lines":["나라들이 **기후변화 협약(Climate Change Convention)** 에 대응하기로 했어요.","그 답으로 나온 여섯 가지 실천이 **생태질서 회복 움직임(Ecological Order Restoration)** 이에요.","그 바탕에 깔린 생각이 **생태주의(Ecologism)** 이고, 그 정신으로 짓는 것이 친환경건축이에요."]}],"pass2":[{"kind":"points","head":"용어 먼저: **생태학(Ecology)** 와 **생태주의(Ecologism)**","items":["**생태학(Ecology)** 은 생물체간의 상호 관계에 대한 학문이에요.","**생태주의(Ecologism)** 는 그 **생태학(Ecology)** 의 기본정신이에요.","친환경건축은 **생태주의(Ecologism)** 에 입각하여 건축문화를 주도하는 것이에요.","**비오톱(Biotop)** 은 생물이 모여 사는 작은 서식 공간, 곧 소생물권이에요."]},{"kind":"points","head":"배경 두 줄","items":["1992년 **리우환경회의(Rio Conference)** 이후 1997년 **교토의정서(Kyoto Protocol)** 채택으로,","**기후변화 협약(Climate Change Convention)** 에 대응할 정부와 민간분야의 실천 방안과 기술개발이 요구됐어요."]},{"kind":"points","head":"**생태질서 회복 움직임(Ecological Order Restoration)** 여섯 가지","items":["1) 에너지 및 자원의 절감  2) **대체에너지(Alternative Energy)** 개발","3) 생태환경 오염방지 및 보존  4) 자원 및 쓰레기 재활용","5) 녹지공간 확충 및 체계화  6) 소생물권 **비오톱(Biotop)** 조성","앞글자로 절대오재녹비: 절감, 대체, 오염, 재활용, 녹지, 비오톱이에요."]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["협약에 담긴 내용은 순서가 중요하다고 하셨어요. 첫째가 에너지 절감, 둘째가 대체에너지예요.","덜 써야 대체에너지로 제로 에너지가 된다고 하셨어요.","교재에 생태학의 정의가 없어서 생물체 간의 상호 관계에 대한 학문이라고 추가해 두셨대요.","조상이 망친 생태 질서를 우리 세대에 회복시켜 보자는 것이 친환경건축의 존재 이유래요."]}],"pass3":[{"kind":"check","q":"**생태주의(Ecologism)** 의 뜻으로 맞는 것은?","choices":["생물체간의 상호 관계에 대한 학문","생태학의 기본정신","소생물권을 조성하는 기술","건물에 등급을 매기는 기준"],"a":1,"why":"학문은 **생태학(Ecology)**, 그 기본정신이 **생태주의(Ecologism)** 예요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"친환경건축은 생태주의에 입각하여 건축문화를 주도하는 것이다.","ko":"**생태학(Ecology)** 은 학문, **생태주의(Ecologism)** 는 그 기본정신, 친환경건축은 그 정신으로 건축문화를 이끌어요.","tip":"학문 다음 정신 다음 건축, 세 칸 순서로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["여섯 가지의 마지막은 소생물권 **비오톱(Biotop)** 조성이에요. 순서를 바꾸지 않게 조심해요.","**리우환경회의(Rio Conference)** 는 1992년, **교토의정서(Kyoto Protocol)** 는 1997년이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.252,0.063],"c":[0.0385,0.0701,0.2772,0.095],"r":3.8905,"img":"img/E1/walk/p019_h.jpg"},"parts":[{"b":[0.11,0.225,0.81,0.105],"c":[0.0695,0.1875,0.891,0.18],"r":6.6,"img":"img/E1/walk/p019_23_01.jpg","say":"1992년 리우 이후 1997년 교토의정서 채택으로 **기후변화 협약(Climate Change Convention)** 대응이 요구됐어요."},{"b":[0.11,0.345,0.81,0.165],"c":[0.0695,0.329,0.891,0.197],"r":6.0305,"img":"img/E1/walk/p019_23_02.jpg","say":"내용 줄이에요. **생태질서 회복 움직임(Ecological Order Restoration)** 여섯 가지가 여기 다 있어요."},{"b":[0.11,0.585,0.73,0.042],"c":[0.0735,0.5249,0.803,0.1622],"r":6.6009,"img":"img/E1/walk/p019_23_03.jpg","say":"**생태주의(Ecologism)** 는 **생태학(Ecology)** 의 기본정신이라고 적혀 있어요."},{"b":[0.08,0.705,0.69,0.042],"c":[0.0455,0.6493,0.759,0.1533],"r":6.6014,"img":"img/E1/walk/p019_23_04.jpg","say":"친환경건축은 **생태주의(Ecologism)** 에 입각하여 건축문화를 주도하는 것이에요."}]}},{"p":20,"title":"기계론적 세계관 vs 생태학적 세계관, 그리고 건축가 세 사람","terms":["Mechanistic Worldview","Ecological Worldview","Machine Aesthetic","Organic Architecture","Falling water"],"pass1":[{"kind":"say","lines":["건물을 기계로 볼지, 살아 있는 몸으로 볼지가 갈리는 쪽이에요.","**기계론적 세계관(Mechanistic Worldview)** 은 인간중심, **생태학적 세계관(Ecological Worldview)** 은 자연중심이에요.","자연 편에 선 건축가 세 사람이 시대 순서로 나와요."]},{"kind":"analogy","head":"자동차와 사람 몸","scene":"자동차는 부품을 조립하면 어디서나 똑같이 굴러가요. 사람 몸은 피부로 숨 쉬고 땀 흘리며 주변과 주고받아요.","map":[["부품을 조립한 자동차","**기계론적 세계관(Mechanistic Worldview)** 건축 (인간중심)"],["주변과 주고받는 사람 몸","**생태학적 세계관(Ecological Worldview)** 건축 (자연중심)"],["피부로 바깥과 통하기","자연환경과 인공환경의 열린 소통체계"]]}],"pass2":[{"kind":"points","head":"용어 먼저","items":["**기계론적 세계관(Mechanistic Worldview)** 은 세상을 기계처럼 보는 인간중심의 눈이에요.","**생태학적 세계관(Ecological Worldview)** 은 세상을 살아 있는 관계로 보는 자연중심의 눈이에요.","**기계미학(Machine Aesthetic)** 은 기계처럼 반듯한 모습을 아름답다고 보는 생각이에요.","**유기적 건축철학(Organic Architecture)** 은 건축을 자연과 어우러진 살아 있는 몸처럼 짓자는 생각이에요."]},{"kind":"compare","head":"두 세계관 비교: 인간 vs 자연","cols":["항목","기계론적 세계관 건축","생태학적 세계관 건축"],"rows":[["중심","인간중심","자연중심"],["위치","20세기 건축 발전의 바탕","주류에서 일탈한 건축이념"],["이념","**기계미학(Machine Aesthetic)** 적 건축이념","**유기적 건축철학(Organic Architecture)**"],["한 일","20세기 건축 발전을 이끌었어요","기하학적 미학에서 벗어나 자연과 조화"],["더","자료 표기 없음","자연환경과 인공환경의 열린 소통체계 중시"]]},{"kind":"points","head":"**유기적 건축철학(Organic Architecture)** 인물 세 사람","items":["1910년대 F.L Wright. 대표작이 **낙수장(Falling water)** 이에요.","1920년대 후반 Le Corbusier. 다음 쪽에 프랑스 롱샹 성당이 나와요.","1930년대 E.Saarinen. 케네디 공항 TWA 터미널과 의자 디자인이 나와요.","십, 이십, 삼십년대 순서로 라이트, 르 코르뷔지에, 사리넨이에요."]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["시험 때는 네 가지만 알자고 하셨어요. 기계론적 세계관은 근대건축, 생태학적 세계관은 친환경건축이에요.","기계론적은 인간 중심주의, 생태학적은 자연 중심주의예요.","기계론적은 대량생산과 대량소비, 생태학적은 소량 다품종 생산과 지역적 소비예요.","도구적 이성과 변증법적 이성은 표현이 어려워 외우지 않아도 된다고 하셨어요."]}],"pass3":[{"kind":"check","q":"**생태학적 세계관(Ecological Worldview)** 건축에 대한 설명으로 옳지 않은 것은?","choices":["자연중심이다.","주류에서 일탈한 건축이념이다.","20세기 건축 발전의 바탕이 된 기계미학적 건축이념이다.","자연환경과 인공환경의 열린 소통체계를 중시한다."],"a":2,"why":"**기계미학(Machine Aesthetic)** 적 건축이념은 **기계론적 세계관(Mechanistic Worldview)** 건축 쪽이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**기계론적 세계관(Mechanistic Worldview)** 은 인간중심이고 주류, **생태학적 세계관(Ecological Worldview)** 은 자연중심이고 일탈이에요.","세 사람의 순서는 Wright, Le Corbusier, Saarinen 이에요. **낙수장(Falling water)** 는 Wright 예요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p020_h.jpg"},"parts":[{"b":[0.11,0.225,0.7,0.045],"c":[0.075,0.1697,0.77,0.1556],"r":6.5981,"img":"img/E1/walk/p020_23_01.jpg","say":"맨 위 줄이에요. 인간 대 자연으로 두 세계관을 맞세워요."},{"b":[0.11,0.345,0.37,0.042],"c":[0.0915,0.311,0.407,0.11],"r":4.9333,"img":"img/E1/walk/p020_23_02.jpg","say":"**기계론적 세계관(Mechanistic Worldview)** 건축, 괄호에 인간중심이라고 적혀 있어요."},{"b":[0.14,0.405,0.6,0.042],"c":[0.11,0.3593,0.66,0.1333],"r":6.6017,"img":"img/E1/walk/p020_23_03.jpg","say":"20세기 건축 발전의 바탕이 된 **기계미학(Machine Aesthetic)** 적 건축이념이에요."},{"b":[0.08,0.525,0.4,0.042],"c":[0.06,0.491,0.44,0.11],"r":5.3333,"img":"img/E1/walk/p020_23_04.jpg","say":"**생태학적 세계관(Ecological Worldview)** 건축, 괄호에 자연중심이라고 적혀 있어요."},{"b":[0.14,0.585,0.31,0.042],"c":[0.1245,0.551,0.341,0.11],"r":4.1333,"img":"img/E1/walk/p020_23_05.jpg","say":"주류에서 일탈한 건축이념이라고 적혀 있어요."},{"b":[0.16,0.645,0.79,0.125],"c":[0.1205,0.6197,0.869,0.1756],"r":6.5983,"img":"img/E1/walk/p020_23_06.jpg","say":"건축가 세 사람이 연도와 함께 묶여 **유기적 건축철학(Organic Architecture)** 으로 이어져요."}]}},{"p":21,"title":"F.L Wright: Falling water (낙수장)","terms":["Falling water","Organic Architecture"],"pass1":[{"kind":"say","lines":["폭포 위에 앉은 집 사진이에요.","F.L Wright 의 **낙수장(Falling water)** 이고, **유기적 건축철학(Organic Architecture)** 의 대표작이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["영문 Falling water, 우리나라에서는 낙수장이라고 하는 라이트의 역작이라고 하셨어요.","보통은 폭포를 밀어버리고 집을 지었겠지만 라이트는 경관을 최대한 덜 해치려 했대요.","테라스의 가로 길이도 나뭇가지가 뻗어 나가는 형태를 모방한 것이래요.","실내외 석재는 그 지역 펜실베이니아에서 구했고, 가구도 전부 라이트가 설계했대요."]}],"pass3":[{"kind":"check","q":"**낙수장(Falling water)** 을 설계한 사람은 누구일까요?","choices":["F.L Wright","Le Corbusier","E.Saarinen","조셉 페스톤"],"a":0,"why":"**낙수장(Falling water)** 은 1910년대 **유기적 건축철학(Organic Architecture)** 의 인물 F.L Wright 의 작품이에요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p021_h.jpg"},"parts":[{"b":[0.11,0.205,0.4,0.06],"c":[0.09,0.18,0.44,0.11],"r":5.3333,"img":"img/E1/walk/p021_20_01.jpg","say":"캡션이에요. F.L Wright : Falling water (낙수장) 이라고 적혀 있어요."},{"b":[0.07,0.31,0.88,0.64],"c":[0.026,0.278,0.968,0.704],"r":1.8333,"img":"img/E1/walk/p021_20_02.jpg","say":"숲과 폭포가 그대로 있고 그 위에 집이 얹혀 있어요."},{"b":[0.44,0.46,0.28,0.2],"c":[0.426,0.444,0.308,0.232],"r":1.7701,"img":"img/E1/walk/p021_20_03.jpg","say":"가로로 길게 뻗은 테라스예요. 나뭇가지가 뻗는 모습을 닮았어요."}]}},{"p":22,"title":"Le Corbusie: 프랑스 롱샹 성당","terms":["Organic Architecture"],"pass1":[{"kind":"say","lines":["지붕이 크게 휘어 올라간 성당 사진이에요.","프랑스 롱샹 성당이고, **유기적 건축철학(Organic Architecture)** 의 두 번째 사례예요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["슬라이드의 이 건물은 빌라 사보아가 아니라 롱샹 성당이라고 짚어 주셨어요.","기계론적 미학의 끝을 달리던 르 코르뷔지에가 후대에 이런 유기체적 건축물도 설계했대요.","잔해를 가지고 콘크리트를 만들었고, 사면의 입면이 다 다르대요.","창의 각도가 다 달라서 빛의 방향을 계산한 건물이라고 하셨어요."]}],"pass3":[{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드 표기는 'Le Corbusie' 예요. 통상 표기는 'Le Corbusier' 예요.","이 사진은 빌라 사보아가 아니라 롱샹 성당이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p022_h.jpg"},"parts":[{"b":[0.11,0.225,0.36,0.045],"c":[0.092,0.1925,0.396,0.11],"r":4.8,"img":"img/E1/walk/p022_20_01.jpg","say":"캡션이에요. 슬라이드에는 'Le Corbusie : 프랑스 롱샹 성당' 으로 적혀 있어요."},{"b":[0.245,0.305,0.51,0.69],"c":[0.2195,0.241,0.561,0.759],"r":0.9855,"img":"img/E1/walk/p022_20_02.jpg","say":"네모 반듯한 근대건축과 달리 곡면으로 된 건물이에요."},{"b":[0.31,0.42,0.45,0.23],"c":[0.2875,0.404,0.495,0.262],"r":2.5191,"img":"img/E1/walk/p022_20_03.jpg","say":"휘어 올라간 지붕이에요. 배 밑바닥처럼 두껍게 얹혀 있어요."}]}},{"p":23,"title":"E.Saarinen: 케네디 공항 TWA 터미널 (1)","terms":["Organic Architecture"],"pass1":[{"kind":"say","lines":["공항 터미널인데 지붕이 새의 날개처럼 생겼어요.","E.Saarinen 의 케네디 공항 TWA 터미널이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["에로 사리넨의 케네디 공항 TWA 터미널이라고 하셨어요.","옆에서 보면 새 같다고 하셨어요.","네모 반듯하게 짓던 근대건축과는 방향성이 다른 것을 볼 수 있대요."]}],"pass4":[],"pass3":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p023_h.jpg"},"parts":[{"b":[0.12,0.2,0.42,0.065],"c":[0.099,0.1775,0.462,0.11],"r":5.6,"img":"img/E1/walk/p023_20_01.jpg","say":"캡션이에요. E.Saarinen : 케네디 공항 TWA 터미널이에요."},{"b":[0.06,0.35,0.88,0.59],"c":[0.016,0.3205,0.968,0.649],"r":1.9887,"img":"img/E1/walk/p023_20_02.jpg","say":"옆에서 본 모습이에요. 지붕이 곡면으로 크게 휘어요."},{"b":[0.45,0.46,0.4,0.24],"c":[0.43,0.444,0.44,0.272],"r":2.1569,"img":"img/E1/walk/p023_20_03.jpg","say":"날개처럼 펼쳐진 지붕이에요. **유기적 건축철학(Organic Architecture)** 의 모습이에요."}]}},{"p":24,"title":"E.Saarinen: 케네디 공항 TWA 터미널 (2)","terms":["Organic Architecture"],"pass1":[{"kind":"say","lines":["같은 터미널을 정면에서 찍은 흑백 사진이에요.","이번에는 정말 날개를 편 새처럼 보여요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["다음 장에는 정말 나는 새처럼 보인다고 하셨어요.","고래를 형상화한 건축물도 있을 만큼 모티브를 자연에서 가져온 유기적 건축물이 많대요.","이런 흐름이 **유기적 건축철학(Organic Architecture)** 이에요."]}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p024_h.jpg"},"parts":[{"b":[0.115,0.215,0.42,0.05],"c":[0.094,0.185,0.462,0.11],"r":5.6,"img":"img/E1/walk/p024_20_01.jpg","say":"캡션은 앞 쪽과 같아요. 케네디 공항 TWA 터미널이에요."},{"b":[0.18,0.31,0.63,0.675],"c":[0.1485,0.2575,0.693,0.7425],"r":1.2444,"img":"img/E1/walk/p024_20_02.jpg","say":"밤에 정면에서 찍은 사진이에요."},{"b":[0.19,0.58,0.62,0.18],"c":[0.159,0.564,0.682,0.212],"r":4.2893,"img":"img/E1/walk/p024_20_03.jpg","say":"가운데가 낮고 양쪽이 올라간 지붕이 새가 날개를 편 모습이에요."}]}},{"p":25,"title":"E.Saarinen: Tulip Chair / Arm Chair","terms":["Organic Architecture"],"pass1":[{"kind":"say","lines":["이번에는 건물이 아니라 의자예요.","왼쪽이 Tulip Chair, 오른쪽이 Arm Chair 이고 둘 다 E.Saarinen 의 작품이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["왼쪽은 튤립 체어, 오른쪽은 암체어라고 짚어 주셨어요.","합판이나 플라스틱을 구부려 인체에 맞는 곡선 형태를 넣은 가구 디자이너 중 한 사람이 사리넨이래요.","외다리 식탁과 의자를 보면 거의 다 사리넨을 따라 한 것이라고 하셨어요."]}],"pass3":[{"kind":"check","q":"Tulip Chair / Arm Chair 를 디자인한 사람은 누구일까요?","choices":["F.L Wright","Le Corbusier","E.Saarinen","조셉 페스톤"],"a":2,"why":"의자 둘 다 E.Saarinen 의 작품이에요. **유기적 건축철학(Organic Architecture)** 은 가구까지 이어졌어요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.2244,0.063],"c":[0.0391,0.0701,0.2484,0.095],"r":3.4863,"img":"img/E1/walk/p025_h.jpg"},"parts":[{"b":[0.11,0.225,0.4,0.045],"c":[0.09,0.1925,0.44,0.11],"r":5.3333,"img":"img/E1/walk/p025_20_01.jpg","say":"캡션이에요. E.Saarinen : Tulip Chair / Arm Chair 예요."},{"b":[0.11,0.34,0.41,0.3],"c":[0.0895,0.324,0.451,0.332],"r":1.8112,"img":"img/E1/walk/p025_20_02.jpg","say":"왼쪽 위가 Tulip Chair 예요. 다리가 하나인 받침이 튤립 같아요."},{"b":[0.1,0.635,0.42,0.36],"c":[0.079,0.604,0.462,0.396],"r":1.5556,"img":"img/E1/walk/p025_20_03.jpg","say":"아래 사진은 튤립 체어와 외다리 식탁을 함께 쓴 실내예요."},{"b":[0.54,0.41,0.41,0.4],"c":[0.5195,0.39,0.451,0.44],"r":1.3667,"img":"img/E1/walk/p025_20_04.jpg","say":"오른쪽이 Arm Chair 예요. 팔걸이가 몸을 감싸는 곡선이에요."}]}},{"p":26,"title":"대안건축으로서의 친환경건축: 의지와 일반적 목표 네 가지","terms":["Alternative Architecture","Community","Sustainable Development","Maintenance","Renewable Resources","Habitat","Landscape","Consumption-dependent Economy","Natural Ecosystem"],"pass1":[{"kind":"say","lines":["친환경건축이 왜 '대안' 인지 정리하는 쪽이에요.","한 번 쓰고 버리던 건축 대신 **대안건축(Alternative Architecture)** 을 내놓는 거예요.","여기에 일반적 목표 네 가지가 나와요. 시험에 그대로 나올 수 있어요."]},{"kind":"analogy","head":"일회용 컵과 도서관 책","scene":"일회용 컵은 한 번 쓰고 버려서 쓰레기가 쌓여요. 도서관 책은 빌려 읽고 돌려주니 다음 사람도 또 읽어요.","map":[["한 번 쓰고 버리는 일회용 컵","**소비 의존형 경제체계(Consumption-dependent Economy)**"],["빌려 읽고 돌려주는 책","자연의 순환체계와 **재생이 가능한 자원(Renewable Resources)** 활용"],["도서관의 한 회원이 되기","건축을 **자연생태계(Natural Ecosystem)** 의 일부로 편입"]]}],"pass2":[{"kind":"points","head":"용어 먼저","items":["**대안건축(Alternative Architecture)** 은 기존 건축을 반성하고 새 길을 내놓는 건축이에요.","**유지관리(Maintenance)** 는 다 지은 건물을 쓰면서 고치고 돌보는 일이에요.","**재생이 가능한 자원(Renewable Resources)** 은 써도 자연이 다시 채워 주는 자원이에요.","**서식(Habitat)** 은 동물과 식물이 자리 잡고 사는 것, **경관(Landscape)** 은 건물 주위 풍경이에요."]},{"kind":"points","head":"의지 두 줄","items":["구조 방식에서부터 설비, 재처리시설까지 자연친화적 환경을 조성하여,","더불어 사는 **공동체(Community)** 와 **지속가능한 개발(Sustainable Development)** 적 대안을 찾아가자는 의지예요."]},{"kind":"points","head":"일반적 목표 네 가지","items":["1) 건축물 시공과 **유지관리(Maintenance)** 에 필요한 에너지 & 자원의 수요 최소화","2) 자연의 순환체계와 **재생이 가능한 자원(Renewable Resources)** 활용","3) 다양한 종의 동물과 식물의 **서식(Habitat)** 가능","4) 건축물을 주위 **경관(Landscape)** 과 어우러지게 배치, 건강한 생활 가능케 함"]},{"kind":"points","head":"앞글자로 외우기: 최순서경","items":["최: 시공과 **유지관리(Maintenance)** 의 에너지 & 자원 수요 최소화","순: 자연의 순환체계와 **재생이 가능한 자원(Renewable Resources)**","서: 다양한 종의 동물과 식물의 **서식(Habitat)**","경: 주위 **경관(Landscape)** 과 어우러진 배치와 건강한 생활"]},{"kind":"points","head":"맨 아래 두 줄: 왜 대안일까요?","items":["기존의 일방적인 **소비 의존형 경제체계(Consumption-dependent Economy)** 가 과소비와 환경오염을 야기했어요.","그래서 건축 자체도 **자연생태계(Natural Ecosystem)** 의 일부로 편입시켜 전체 시스템을 구성해요.","주문: **자연에서 빌려 쓰고, 돌려주며 순환시켜요.**"]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["대안건축으로서 친환경건축의 목표가 넷이라고 하셨어요.","셋째는 동물과 식물의 서식 가능성을 건축 환경에서 보장하는 것이래요.","생태학적 접근은 시공, 유지, 폐기까지 건물의 전 생애 주기에 걸쳐 한다고 하셨어요.","기술이 인간을 해치면 안 된다고 하셨어요."]}],"pass3":[{"kind":"check","q":"옥상과 외벽에 새와 곤충이 머물 식재 공간을 만들었어요. 가장 가까운 일반적 목표는?","choices":["에너지 & 자원의 수요 최소화","자연의 순환체계와 재생이 가능한 자원 활용","다양한 종의 동물과 식물의 서식 가능","주위 경관과 어우러진 배치"],"a":2,"why":"새와 곤충이 살 자리를 만드는 것은 목표 3, 동식물의 **서식(Habitat)** 이에요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"시공과 유지관리 에너지 최소화, 재생이 가능한 자원 활용, 동식물의 서식 가능, 경관과 어우러진 배치다.","ko":"**대안건축(Alternative Architecture)** 으로서 친환경건축의 일반적 목표 네 가지예요.","tip":"최순서경 네 글자로 순서까지 같이 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["목표 1은 수요 '최소화' 예요. 공급 확대가 아니고, 시공과 **유지관리(Maintenance)** 두 단계 모두예요.","건축은 **자연생태계(Natural Ecosystem)** 과 분리된 독립 시스템이 아니라 그 일부로 편입돼요.","의지 줄의 두 낱말은 **공동체(Community)** 와 **지속가능한 개발(Sustainable Development)** 이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.3912,0.063],"c":[0.0316,0.0912,0.4304,0.095],"r":6.0407,"img":"img/E1/walk/p026_h.jpg"},"parts":[{"b":[0.11,0.245,0.79,0.105],"c":[0.0705,0.2097,0.869,0.1756],"r":6.5983,"img":"img/E1/walk/p026_25_01.jpg","say":"의지 두 줄이에요. **공동체(Community)** 와 **지속가능한 개발(Sustainable Development)** 적 대안을 찾아가자는 말이에요."},{"b":[0.11,0.365,0.14,0.042],"c":[0.08,0.331,0.2,0.11],"r":2.4242,"img":"img/E1/walk/p026_25_02.jpg","say":"'일반적 목표' 라고 적힌 작은 제목이에요."},{"b":[0.13,0.425,0.75,0.105],"c":[0.0925,0.3942,0.825,0.1667],"r":6.5987,"img":"img/E1/walk/p026_25_03.jpg","say":"목표 1과 2예요. 수요 최소화와 **재생이 가능한 자원(Renewable Resources)** 활용이에요."},{"b":[0.13,0.545,0.74,0.105],"c":[0.093,0.5153,0.814,0.1645],"r":6.5978,"img":"img/E1/walk/p026_25_04.jpg","say":"목표 3과 4예요. 동식물 **서식(Habitat)** 과 **경관(Landscape)** 배치예요."},{"b":[0.085,0.725,0.78,0.042],"c":[0.046,0.6593,0.858,0.1733],"r":6.6013,"img":"img/E1/walk/p026_25_05.jpg","say":"**소비 의존형 경제체계(Consumption-dependent Economy)** 가 과소비와 환경오염을 불렀어요."},{"b":[0.085,0.785,0.75,0.042],"c":[0.0475,0.7227,0.825,0.1667],"r":6.5987,"img":"img/E1/walk/p026_25_06.jpg","say":"건축 자체도 **자연생태계(Natural Ecosystem)** 의 일부로 편입시켜요."}]}},{"p":27,"title":"설계 개요: 순환고리를 찾는 설계와 One-Way Process","terms":["Circulation Loop","One-Way Process","Circulation System","Human-centered Design Methodology","Environmental Load","Comfort"],"pass1":[{"kind":"say","lines":["여기서부터 순환 이야기예요.","기존 건축은 들어온 것이 더러워져 나가기만 하는 **원웨이 프로세스(One-Way Process)** 였어요.","친환경건축은 건물과 주변환경 사이의 **순환고리(Circulation Loop)** 를 찾아요.","주문: **자연에서 빌려 쓰고, 돌려주며 순환시켜요.**"]}],"pass2":[{"kind":"points","head":"용어 먼저","items":["**인간위주 건축설계방법론(Human-centered Design Methodology)** 은 사람 편한 것만 생각하던 옛 설계 방식이에요.","**순환고리(Circulation Loop)** 는 건물과 주변환경이 서로 주고받으며 도는 연결 고리예요.","**환경부하(Environmental Load)** 는 건물이 지구와 주변환경에 지우는 짐이에요.","**쾌적(Comfort)** 은 건물 안 사람이 편하고 기분 좋게 지내는 상태예요."]},{"kind":"points","head":"글 네 줄 그대로","items":["**인간위주 건축설계방법론(Human-centered Design Methodology)** 에 대한 회의감에서 비롯됐어요.","개별건축물과 주변환경과의 상호간 **순환고리(Circulation Loop)** 를 찾는 것에서 시작해요.","에너지, 재료, 녹지, 대기, 물과의 관계 속에서 건축물을 해석해요.","목표는 지구와 외부환경의 부하 절감 및 인간의 **쾌적(Comfort)** 이에요."]},{"kind":"compare","head":"왼쪽 그림 **원웨이 프로세스(One-Way Process)** 의 네 줄","cols":["흐름","들어오는 것","나가는 것"],"rows":[["공기","Fresh Air","Dirty Air"],["에너지","Energy(Electronic/Gas)","Energy(Heating Air)"],["물","Clean Water","Dirty Water"],["제품","Product","Trash"]]},{"kind":"points","head":"오른쪽 그림: 친환경건축","items":["가운데에 Circulation 이라고 적혀 있고 둘레를 Energy, Air, Material, Water 가 감싸요.","이것이 다섯 **순환체계(Circulation System)** 중 네 가지이고, 왼쪽 나무 그림이 녹지예요.","곧 에너지, 재료, 녹지, 대기, 물 다섯 가지예요."]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["건물이 없었다면 비는 땅에 스며들어 지하수가 되고 바다로 나가 다시 비가 됐다고 하셨어요.","건축물이 들어서면 그 면적만큼 순환이 끊긴다고 하셨어요.","그림 1에서 끊기는 순환이 다섯이고, 오른쪽에 녹지가 안 적혀 있지만 왼쪽 나무가 녹지래요.","순환을 고려한 친환경건축 설계의 다섯 대상은 꼭 말할 수 있어야 한다고 하셨어요."]}],"pass3":[{"kind":"check","q":"**원웨이 프로세스(One-Way Process)** 의 네 줄로 옳지 않은 것은?","choices":["Fresh Air 가 Dirty Air 로","Energy(Electronic/Gas) 가 Energy(Heating Air) 로","Clean Water 가 Dirty Water 로","Trash 가 Product 로"],"a":3,"why":"Product 가 Trash 로 가요. 방향을 뒤집으면 **원웨이 프로세스(One-Way Process)** 가 아니에요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"순환을 고려한 친환경건축 설계의 대상은 에너지, 재료, 녹지, 대기, 물 다섯 가지다.","ko":"다섯 **순환체계(Circulation System)** 이고, 목표는 **환경부하(Environmental Load)** 절감과 인간의 **쾌적(Comfort)** 이에요.","tip":"앞글자로 '에재녹대물' 이라고 외워요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.141,0.063],"c":[0.0217,0.0701,0.2,0.095],"r":2.807,"img":"img/E1/walk/p027_h.jpg"},"parts":[{"b":[0.11,0.225,0.59,0.042],"c":[0.0805,0.1804,0.649,0.1311],"r":6.6006,"img":"img/E1/walk/p027_24_01.jpg","say":"**인간위주 건축설계방법론(Human-centered Design Methodology)** 에 대한 회의감에서 비롯됐어요."},{"b":[0.11,0.285,0.73,0.042],"c":[0.0735,0.2249,0.803,0.1622],"r":6.6009,"img":"img/E1/walk/p027_24_02.jpg","say":"굵게 표시된 **순환고리(Circulation Loop)** 를 찾는 것에서 시작해요."},{"b":[0.11,0.345,0.68,0.042],"c":[0.076,0.2904,0.748,0.1511],"r":6.6005,"img":"img/E1/walk/p027_24_03.jpg","say":"굵게 표시된 다섯 가지예요. 에너지, 재료, 녹지, 대기, 물이에요."},{"b":[0.11,0.405,0.58,0.042],"c":[0.081,0.3616,0.638,0.1289],"r":6.5994,"img":"img/E1/walk/p027_24_04.jpg","say":"목표 줄이에요. 부하 절감 '및' 인간의 **쾌적(Comfort)** 이에요."},{"b":[0.05,0.5,0.48,0.45],"c":[0.026,0.4775,0.528,0.495],"r":1.4222,"img":"img/E1/walk/p027_24_05.jpg","say":"왼쪽 그림이에요. **원웨이 프로세스(One-Way Process)**, 기존의 건축이에요."},{"b":[0.55,0.5,0.43,0.45],"c":[0.527,0.4775,0.473,0.495],"r":1.2741,"img":"img/E1/walk/p027_24_06.jpg","say":"오른쪽 그림이에요. 가운데 Circulation 이 도는 친환경건축이에요."}]}},{"p":28,"title":"순환체계별 적용기술 다섯 줄 (표3)","terms":["Applied Technology","Circulation System","Renewable Energy","Regional Green Network","Rainwater","Wastewater","Infiltration"],"pass1":[{"kind":"say","lines":["다섯 **순환체계(Circulation System)** 마다 실제로 쓰는 방법이 한 줄씩 적힌 표예요.","이 다섯 줄이 **적용기술(Applied Technology)** 이고, 앞으로 배울 내용의 목차예요."]}],"pass2":[{"kind":"points","head":"용어 먼저","items":["**적용기술(Applied Technology)** 은 순환체계마다 실제 설계에 쓰는 방법 한 줄이에요.","**우수(Rainwater)** 는 하늘에서 내린 빗물, **오수(Wastewater)** 는 쓰고 난 더러워진 물이에요.","**침투(Infiltration)** 는 빗물이 흙 속으로 스며드는 것이에요.","**광역녹지체계(Regional Green Network)** 는 단지를 넘어 넓게 이어진 녹지 연결망이에요."]},{"kind":"compare","head":"표3: **순환체계(Circulation System)** 별 **적용기술(Applied Technology)**","cols":["순환체계","적용기술"],"rows":[["에너지","**신재생에너지(Renewable Energy)** 를 위주로 에너지 순환 도모"],["건축재료","자연순환적 재료 채택, 생산과 운송에 사용되는 에너지 최소화"],["녹지","**광역녹지체계(Regional Green Network)** 와의 연계성 고려"],["물","빗물과 **오수(Wastewater)** 분리, **우수(Rainwater)** 는 **침투(Infiltration)** 유도"],["대기","실내외의 공기 순환"]]},{"kind":"points","head":"한 줄씩 쉬운 말로","items":["에너지는 **신재생에너지(Renewable Energy)**, 재료는 자연순환과 운송 에너지 줄이기예요.","녹지는 **광역녹지체계(Regional Green Network)** 와 이어 주기예요.","물은 **우수(Rainwater)** 와 **오수(Wastewater)** 를 나누고 빗물은 땅에 **침투(Infiltration)** 시켜요.","대기는 실내외 공기가 돌게 해요."]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["표 3의 활용 기술에 BIPV 같은 낯선 말이 있는데 다 앞으로 배울 것이라고 하셨어요.","중간고사 때쯤 표 3을 보면 무슨 말인지 다 알게 된다고 하셨어요."]}],"pass3":[{"kind":"check","q":"**순환체계(Circulation System)** 과 **적용기술(Applied Technology)** 의 연결로 옳지 않은 것은?","choices":["에너지: 신재생 에너지를 위주로 에너지 순환 도모","녹지: 광역녹지체계와의 연계성 고려","물: 빗물과 오수 분리, 우수는 침투 유도","대기: 생산과 운송에 사용되는 에너지 최소화"],"a":3,"why":"생산과 운송 에너지 최소화는 건축재료 줄이에요. 대기는 실내외의 공기 순환이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'**광역녹지체계(Regional Green Network)** 와의 연계성' 은 녹지, '실내외의 공기 순환' 은 대기예요.","**우수(Rainwater)** 는 저장하고 **침투(Infiltration)** 시키고, **오수(Wastewater)** 는 따로 처리해요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.0861,0.141,0.063],"c":[0.0217,0.0701,0.2,0.095],"r":2.807,"img":"img/E1/walk/p028_h.jpg"},"parts":[{"b":[0.11,0.225,0.3,0.042],"c":[0.095,0.191,0.33,0.11],"r":4.0,"img":"img/E1/walk/p028_23_01.jpg","say":"표3 제목이에요. 순환체계별 **적용기술(Applied Technology)** 이에요."},{"b":[0.12,0.345,0.59,0.042],"c":[0.0905,0.3004,0.649,0.1311],"r":6.6006,"img":"img/E1/walk/p028_23_02.jpg","say":"에너지 줄이에요. **신재생에너지(Renewable Energy)** 위주예요."},{"b":[0.12,0.405,0.84,0.042],"c":[0.076,0.3327,0.924,0.1867],"r":6.5988,"img":"img/E1/walk/p028_23_03.jpg","say":"건축재료 줄이에요. 생산과 운송 에너지까지 줄여요."},{"b":[0.12,0.465,0.44,0.042],"c":[0.098,0.431,0.484,0.11],"r":5.8667,"img":"img/E1/walk/p028_23_04.jpg","say":"녹지 줄이에요. **광역녹지체계(Regional Green Network)** 와의 연계성이에요."},{"b":[0.12,0.525,0.47,0.042],"c":[0.0965,0.491,0.517,0.11],"r":6.2667,"img":"img/E1/walk/p028_23_05.jpg","say":"물 줄이에요. 분리하고 **침투(Infiltration)** 를 유도해요."},{"b":[0.12,0.585,0.32,0.042],"c":[0.104,0.551,0.352,0.11],"r":4.2667,"img":"img/E1/walk/p028_23_06.jpg","say":"대기 줄이에요. 실내외의 공기 순환이에요."}]}},{"p":29,"title":"1) 에너지 순환체계: 신재생에너지와 미기후","terms":["Fossil Energy","Renewable Energy","Microclimate","Broadleaf Tree","Conifer","Biomass","Alternative Energy"],"pass1":[{"kind":"say","lines":["다섯 순환 중 첫 번째, 에너지 차례예요.","탄소를 내지 않는 **신재생에너지(Renewable Energy)** 를 쓰고, **미기후(Microclimate)** 를 이용해 냉난방을 줄여요.","나무 심는 자리만 잘 골라도 냉난방비가 줄어요."]},{"kind":"analogy","head":"건물에 입히는 겨울 패딩","scene":"겨울에 찬바람이 부는 쪽은 패딩으로 꽁꽁 감싸요. 건물 둘레의 나무도 바람 쪽은 막고 해 드는 쪽은 열어 줘요.","map":[["사람 몸","건물"],["찬바람 쪽을 감싼 겨울 패딩","북쪽의 **침엽수(Conifer)**"],["몸 바로 옆의 공기","**미기후(Microclimate)** (지표면에서 1.5m 정도까지)"]]}],"pass2":[{"kind":"points","head":"용어 먼저","items":["**화석에너지(Fossil Energy)** 는 석유, 석탄처럼 캐서 쓰고 나면 없어지는 에너지예요.","**신재생에너지(Renewable Energy)** 는 탄소를 내보내지 않고 자연에서 다시 얻는 에너지예요.","**미기후(Microclimate)** 는 지표면에서 1.5m 정도까지의 기후예요.","**활엽수(Broadleaf Tree)** 는 잎이 넓은 나무, **침엽수(Conifer)** 는 잎이 바늘 같은 나무예요."]},{"kind":"points","head":"배경 세 줄","items":["**화석에너지(Fossil Energy)** 자원 고갈이 예상돼요.","지속적인 지구온난화 진행 및 이상기후현상이 나타나요.","한정된 에너지, 환경오염에 관한 에너지원 고민이 필요해요. 답은 대안에너지예요."]},{"kind":"points","head":"에너지 순환 방법 두 가지","items":["1) 탄소를 배출하지 않는 **신재생에너지(Renewable Energy)** 위주의 건축계획이에요.","2) **미기후(Microclimate)** 를 이용한 냉난방 설계계획이에요.","괄호 안 설명 그대로 **미기후(Microclimate)** 는 지표면에서 1.5m 정도까지의 기후예요.","예시는 남쪽의 **활엽수(Broadleaf Tree)** + 북쪽의 **침엽수(Conifer)** 예요. 앞글자로 남활북침이에요."]},{"kind":"points","head":"**대체에너지(Alternative Energy)** 목록","items":["태양에너지(광/열), 풍력, 조력, 파력, 지열, **바이오매스(Biomass)** 등이에요.","앞글자로 태풍조파지바예요.","석탄, 석유 같은 **화석에너지(Fossil Energy)** 는 이 목록에 없어요.","그리고 설계 초기부터의 통합적 고려가 필요해요."]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["에너지 순환의 핵심은 탄소를 배출하지 않는 신재생에너지를 만들어 내는 것이래요. 다만 덜 쓰는 것이 먼저예요.","미기후는 지표면에서 1.5m 정도 높이의 기후대, 곧 사람이 계속 접하는 지표면의 대기래요.","남쪽 활엽수는 여름에 햇빛을 가리고 가을에 잎이 져서 겨울에는 해가 들어온다고 하셨어요.","북쪽 침엽수는 겨울에도 잎이 있어 북서풍을 막아 난방 에너지를 줄여 준대요."]}],"pass3":[{"kind":"check","q":"**미기후(Microclimate)** 의 뜻으로 맞는 것은?","choices":["지표면에서 1.5m 정도까지의 기후","지표면에서 15m 정도까지의 기후","한 나라 전체의 평균 기후","건물 안의 공기 상태"],"a":0,"why":"슬라이드 괄호 그대로 지표면에서 1.5m 정도까지의 기후예요."},{"kind":"check","q":"슬라이드의 **대체에너지(Alternative Energy)** 목록에 없는 것은?","choices":["조력","파력","바이오매스","석탄"],"a":3,"why":"목록은 태양에너지(광/열), 풍력, 조력, 파력, 지열, **바이오매스(Biomass)** 등이에요. 석탄은 **화석에너지(Fossil Energy)** 예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**미기후(Microclimate)** 는 1.5m 예요. 15m 나 150m 가 아니에요.","남쪽이 **활엽수(Broadleaf Tree)**, 북쪽이 **침엽수(Conifer)** 예요. 뒤집으면 틀려요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2602,0.063],"c":[0.0381,0.0912,0.2862,0.095],"r":4.0168,"img":"img/E1/walk/p029_h.jpg"},"parts":[{"b":[0.11,0.245,0.76,0.165],"c":[0.072,0.229,0.836,0.197],"r":5.6582,"img":"img/E1/walk/p029_24_01.jpg","say":"배경 세 줄이에요. 맨 끝에 대안에너지라고 적혀 있어요."},{"b":[0.11,0.485,0.14,0.042],"c":[0.08,0.451,0.2,0.11],"r":2.4242,"img":"img/E1/walk/p029_24_02.jpg","say":"'에너지 순환' 이라고 적힌 작은 제목이에요."},{"b":[0.14,0.545,0.61,0.042],"c":[0.1095,0.4982,0.671,0.1356],"r":6.5978,"img":"img/E1/walk/p029_24_03.jpg","say":"방법 1이에요. 탄소를 배출하지 않는 **신재생에너지(Renewable Energy)** 위주예요."},{"b":[0.14,0.605,0.79,0.042],"c":[0.1005,0.5382,0.869,0.1756],"r":6.5983,"img":"img/E1/walk/p029_24_04.jpg","say":"방법 2예요. 괄호에 1.5m 정도까지라고 적혀 있어요."},{"b":[0.18,0.665,0.39,0.042],"c":[0.1605,0.631,0.429,0.11],"r":5.2,"img":"img/E1/walk/p029_24_05.jpg","say":"예시 줄이에요. 남쪽의 **활엽수(Broadleaf Tree)** + 북쪽의 **침엽수(Conifer)** 예요."},{"b":[0.11,0.785,0.78,0.105],"c":[0.071,0.7508,0.858,0.1733],"r":6.6013,"img":"img/E1/walk/p029_24_06.jpg","say":"**대체에너지(Alternative Energy)** 목록과 설계 초기부터의 통합적 고려예요."}]}},{"p":30,"title":"2) 건축재료 순환체계: 돌아가는 재료를 먼저","terms":["Local Natural Material","Recycling","Environmental Load","Modern Architecture"],"pass1":[{"kind":"say","lines":["다섯 순환 중 두 번째, 재료 차례예요.","흙과 나무는 묻으면 자연으로 돌아가고, 철과 콘크리트와 유리는 그렇지 않아요.","그래서 **지역적 자연적 재료(Local Natural Material)** 와 **재활용(Recycling)** 자재를 먼저 골라요."]}],"pass2":[{"kind":"points","head":"용어 먼저","items":["**지역적 자연적 재료(Local Natural Material)** 는 주변에서 구하기 쉽고 자연에서 온 건축 재료예요.","**재활용(Recycling)** 은 쓰던 자재를 버리지 않고 다시 살려 쓰는 것이에요.","**환경부하(Environmental Load)** 는 건물이 지구와 주변환경에 지우는 짐이에요."]},{"kind":"compare","head":"옛 건축 재료와 **현대건축(Modern Architecture)** 재료","cols":["구분","옛 건축","현대건축"],"rows":[["재료","흙, 나무","철, 콘크리트, 유리 등"],["쓰는 동안","자연에서 온 재료","유해 물질 발생"],["버린 뒤","쉽게 자연으로 돌아감","폐기 후 **환경부하(Environmental Load)** 가중"]]},{"kind":"points","head":"건축재료 선택 원칙 한 줄","items":["주변에서 구하기 쉽고, **지역적 자연적 재료(Local Natural Material)** 와,","**재활용(Recycling)**, 재사용 및 재생가능한 자재를,","우선적으로 선택하여 디자인해요.","표3의 재료 줄과 같은 말이에요. 자연순환적 재료 채택, 생산과 운송 에너지 최소화예요."]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["재료 순환은 앞서 본 토속건축 그 자체라고 하셨어요.","한 줄로 요약하면 주변에서 구하자, 그중 자연적인 재료를 쓰자, 쓴 것은 재활용하자래요.","재활용을 생각하면 왁싱과 코팅을 많이 하지 않는다고 하셨어요.","애초에 재활용할 것을 생각해서 가공하라는 이야기예요."]}],"pass3":[{"kind":"check","q":"건축재료 순환체계의 선택 원칙으로 맞는 것은?","choices":["철과 콘크리트와 유리의 사용을 법으로 금지한다","지역적 자연적 재료와 재활용 자재를 우선적으로 선택한다","값이 가장 싼 재료를 먼저 고른다","수입 재료를 우선한다"],"a":1,"why":"슬라이드는 **지역적 자연적 재료(Local Natural Material)** 와 **재활용(Recycling)** 자재를 '우선적으로 선택' 하라고 해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["철, 콘크리트, 유리를 금지한 것이 아니에요. 좋은 재료를 우선적으로 선택하라는 말이에요.","**환경부하(Environmental Load)** 가중은 폐기 '후' 의 이야기예요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2977,0.063],"c":[0.0362,0.0912,0.3275,0.095],"r":4.5965,"img":"img/E1/walk/p030_h.jpg"},"parts":[{"b":[0.11,0.245,0.65,0.042],"c":[0.0775,0.1938,0.715,0.1445],"r":6.5975,"img":"img/E1/walk/p030_23_01.jpg","say":"옛 건축의 흙, 나무는 쉽게 자연으로 돌아가는 재료라고 적혀 있어요."},{"b":[0.11,0.305,0.67,0.105],"c":[0.0765,0.2831,0.737,0.1489],"r":6.5995,"img":"img/E1/walk/p030_23_02.jpg","say":"**현대건축(Modern Architecture)** 재료는 유해 물질 발생과 폐기 후 **환경부하(Environmental Load)** 가중이에요."},{"b":[0.08,0.485,0.74,0.105],"c":[0.043,0.4553,0.814,0.1645],"r":6.5978,"img":"img/E1/walk/p030_23_03.jpg","say":"결론 줄이에요. **지역적 자연적 재료(Local Natural Material)** 와 **재활용(Recycling)** 자재를 우선 선택해요."}]}},{"p":31,"title":"3) 녹지 순환체계: 방법 두 가지와 생태녹지의 기능","terms":["Regional Green Network","Transpiration","Heat Island","Circulation System"],"pass1":[{"kind":"say","lines":["다섯 순환 중 세 번째, 녹지 차례예요.","녹지를 만드는 방법이 두 가지, 녹지가 해 주는 일이 여러 가지예요.","건물 밖을 녹지로 만들고, 더 나아가 건물 자체를 녹화해요."]},{"kind":"analogy","head":"땀 흘리는 몸, 초록 피부","scene":"더운 날 사람은 땀을 흘려 몸을 식혀요. 식물도 잎으로 물을 내보내 주변을 식혀요.","map":[["땀이 마르며 몸이 식음","식물의 **증산작용(Transpiration)** 으로 온도 저감"],["사람 몸의 피부","건물의 외피, 곧 입면과 지붕"],["피부를 덮어 주는 옷","토양층이 콘크리트 노화를 막아 줌"]]}],"pass2":[{"kind":"points","head":"용어 먼저","items":["**증산작용(Transpiration)** 은 식물이 잎으로 물을 수증기로 내보내 주변을 식히는 일이에요.","**열섬화 현상(Heat Island)** 은 도시가 주변보다 섬처럼 뜨거워지는 현상이에요.","**광역녹지체계(Regional Green Network)** 는 단지를 넘어 넓게 이어진 녹지 연결망이에요."]},{"kind":"compare","head":"녹지를 만드는 방법 두 가지","cols":["방법","내용"],"rows":[["기본","건축물을 제외한 공간을 녹지로 활용하여 구성"],["적극적","건축물 자체를 녹화 (입면, 지붕 등을 녹화)"]]},{"kind":"points","head":"생태녹지 및 조경의 기능 (앞쪽 네 줄)","items":["이산화탄소 흡수: 공기질 향상이에요.","증발 및 **증산작용(Transpiration)**: **열섬화 현상(Heat Island)** 제거, 온도 저감이에요.","열환경 개선(단열)이에요.","우수유출조절, 과잉 건조 완화예요."]},{"kind":"points","head":"추가기능 두 줄과 외우는 말","items":["추가기능 1: 소리 흡수로 소음경감이에요.","추가기능 2: 건축물 내구성 향상이에요. 토양층이 콘크리트 노화를 방지해요.","앞글자로 이증단우소내라고 외워요.","녹지도 다섯 **순환체계(Circulation System)** 의 하나예요. 주문: **자연에서 빌려 쓰고, 돌려주며 순환시켜요.**"]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["이미 대지는 훼손됐으니 남아 있는 녹지와 건물을 연계시키겠다는 것이 녹지 순환이래요.","방법은 둘, 건축물을 제외한 공간을 다 녹지로 만들기와 옥상과 벽면까지 녹화하는 적극적인 방법이에요.","피부에 알코올 솜을 대면 시원한 것처럼, 식물이 수분을 증발시키며 열섬화를 줄인다고 하셨어요.","우수는 빗물이고, 식물이 흙 속에 빗물을 저장해 주어서 도시 홍수를 막는다고 하셨어요."]}],"pass3":[{"kind":"check","q":"증발 및 **증산작용(Transpiration)** 이 하는 일로 맞는 것은?","choices":["열섬화 현상 제거, 온도 저감","빗물을 지하 탱크에 모음","실내 공기질만 좋게 함","콘크리트를 빨리 굳게 함"],"a":0,"why":"슬라이드 그대로 **열섬화 현상(Heat Island)** 제거와 온도 저감이에요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"이산화탄소 흡수, 증발 및 증산작용, 열환경 개선, 우수유출조절이 생태녹지의 기능이다.","ko":"추가기능으로 소음경감과 건축물 내구성 향상도 있어요.","tip":"이증단우소내 여섯 글자로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["방법 두 가지 중 '적극적' 인 쪽이 건축물 자체를 녹화하는 쪽이에요.","내구성 향상의 이유는 토양층이 콘크리트 노화를 막아 주기 때문이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2422,0.063],"c":[0.039,0.0912,0.2664,0.095],"r":3.7389,"img":"img/E1/walk/p031_h.jpg"},"parts":[{"b":[0.11,0.245,0.77,0.042],"c":[0.0715,0.1804,0.847,0.1711],"r":6.6004,"img":"img/E1/walk/p031_24_01.jpg","say":"주변 생태환경과 연계하는 녹지를 건축물과 유기적 관계 속에서 조성해요."},{"b":[0.11,0.305,0.59,0.042],"c":[0.0805,0.2604,0.649,0.1311],"r":6.6006,"img":"img/E1/walk/p031_24_02.jpg","say":"방법 1이에요. 건축물을 제외한 공간을 녹지로 활용해요."},{"b":[0.17,0.365,0.62,0.042],"c":[0.139,0.3171,0.682,0.1378],"r":6.5989,"img":"img/E1/walk/p031_24_03.jpg","say":"방법 2예요. 적극적으로 건축물 자체를 녹화해요."},{"b":[0.11,0.485,0.28,0.042],"c":[0.096,0.451,0.308,0.11],"r":3.7333,"img":"img/E1/walk/p031_24_04.jpg","say":"'생태녹지 및 조경의 기능' 이라고 적힌 작은 제목이에요."},{"b":[0.13,0.545,0.56,0.165],"c":[0.102,0.529,0.616,0.197],"r":4.1692,"img":"img/E1/walk/p031_24_05.jpg","say":"기능 앞 세 줄이에요. 이산화탄소 흡수, **증산작용(Transpiration)**, 열환경 개선이에요."},{"b":[0.13,0.725,0.73,0.165],"c":[0.0935,0.709,0.803,0.197],"r":5.4349,"img":"img/E1/walk/p031_24_06.jpg","say":"우수유출조절과 추가기능 두 줄이에요. 소음경감과 내구성 향상이에요."}]}},{"p":32,"title":"녹지 순환 사례: GS건설 '미사 강변 센트럴 자이'","terms":["Rain Garden","Eco Road","Crystal Garden","IFLA","Circulation System"],"pass1":[{"kind":"say","lines":["앞 쪽에서 배운 녹지 이야기를 진짜 아파트 단지로 보여 주는 쪽이에요.","단지 전체를 물이 도는 곳으로 만든 사례예요.","이름이 붙은 것이 셋이에요. **레인가든(Rain Garden)**, **에코로드(Eco Road)**, **크리스탈 가든(Crystal Garden)** 이에요."]}],"pass2":[{"kind":"points","head":"용어 먼저","items":["**레인가든(Rain Garden)** 은 빗물을 모아 두는 기능을 가진 정원이에요.","**에코로드(Eco Road)** 는 단지 외곽을 따라 흙길로 포장된 약 1.0km 규모의 길이에요.","**크리스탈 가든(Crystal Garden)** 은 빗물로 만드는 생태연못이에요.","**세계조경가협회(IFLA)** 는 세계 조경가들의 모임이에요."]},{"kind":"points","head":"윗줄 두 개: 상과 목표","items":["2017년 살기 좋은 아파트 최우수상을 받았어요.","2019년 **세계조경가협회(IFLA)** 우수상을 받았어요.","미래 기후변화 대응형 생태 조경을 도입했어요."]},{"kind":"compare","head":"생태 조경 네 가지","cols":["이름","내용"],"rows":[["물길","자연적인 물순환 원리에 가까운 물길"],["**레인가든(Rain Garden)**","빗물 저장기능을 가진 정원"],["**에코로드(Eco Road)**","단지 외곽을 따라 흙길로 포장된 약 1.0km 규모"],["**크리스탈 가든(Crystal Garden)**","빗물로 만드는 생태연못"]]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["하버드 교수와 함께 설계했다고 하셨어요.","조경이 예쁜 것으로 끝나면 안 되고 미래 기후 변화에 대응해야 한다는 목표로 만들었대요.","물이 순환되는 단지를 만들려고 단지 전체를 설계했다고 하셨어요."]}],"pass3":[{"kind":"check","q":"미사 강변 센트럴 자이에서 '빗물로 만드는 생태연못' 의 이름은?","choices":["**레인가든(Rain Garden)**","**에코로드(Eco Road)**","**크리스탈 가든(Crystal Garden)**","완충녹지"],"a":2,"why":"빗물 저장 정원은 **레인가든(Rain Garden)**, 흙길은 **에코로드(Eco Road)**, 생태연못이 **크리스탈 가든(Crystal Garden)** 이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["2017년은 살기 좋은 아파트 최우수상, 2019년이 **세계조경가협회(IFLA)** 우수상이에요.","약 1.0km 는 **에코로드(Eco Road)** 의 규모예요. 다른 이름에 붙이면 틀려요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2422,0.063],"c":[0.039,0.0912,0.2664,0.095],"r":3.7389,"img":"img/E1/walk/p032_h.jpg"},"parts":[{"b":[0.08,0.205,0.34,0.04],"c":[0.063,0.17,0.374,0.11],"r":4.5333,"img":"img/E1/walk/p032_23_01.jpg","say":"사례 이름이에요. GS건설 '미사 강변 센트럴 자이' 예요."},{"b":[0.08,0.31,0.79,0.095],"c":[0.0405,0.2697,0.869,0.1756],"r":6.5983,"img":"img/E1/walk/p032_23_02.jpg","say":"2017년 살기 좋은 아파트 최우수상, 2019년 **세계조경가협회(IFLA)** 우수상이에요."},{"b":[0.13,0.423,0.34,0.034],"c":[0.113,0.385,0.374,0.11],"r":4.5333,"img":"img/E1/walk/p032_23_03.jpg","say":"첫째, 자연적인 물순환 원리에 가까운 물길이에요."},{"b":[0.13,0.473,0.3,0.034],"c":[0.115,0.435,0.33,0.11],"r":4.0,"img":"img/E1/walk/p032_23_04.jpg","say":"둘째, 빗물 저장기능을 가진 **레인가든(Rain Garden)** 이에요."},{"b":[0.12,0.523,0.57,0.034],"c":[0.0915,0.4767,0.627,0.1267],"r":6.5983,"img":"img/E1/walk/p032_23_05.jpg","say":"셋째, 흙길로 포장된 약 1.0km 규모의 **에코로드(Eco Road)** 예요."},{"b":[0.13,0.573,0.37,0.034],"c":[0.1115,0.535,0.407,0.11],"r":4.9333,"img":"img/E1/walk/p032_23_06.jpg","say":"넷째, 빗물로 만드는 생태연못 **크리스탈 가든(Crystal Garden)** 이에요."}]}},{"p":33,"title":"미사 강변 센트럴 자이 배치도와 단지 전경","terms":["Eco Road","Rain Garden","Circulation System"],"pass1":[{"kind":"say","lines":["왼쪽은 단지 배치도, 오른쪽은 위에서 찍은 단지 사진이에요.","앞 쪽에서 이름으로만 본 것들이 실제로 어디 있는지 보여 줘요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["단지 내 정원들이 다 빗물 저장 장소가 됐다고 하셨어요.","그 빗물로 생태연못을 만들고 단지 주변에 흙 산책길을 두었대요.","그냥 잔디밭처럼 보이는 정원이 사실은 **레인가든(Rain Garden)** 이라 빗물이 밑에 저장된대요."]}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2422,0.063],"c":[0.039,0.0912,0.2664,0.095],"r":3.7389,"img":"img/E1/walk/p033_h.jpg"},"parts":[{"b":[0.11,0.205,0.34,0.04],"c":[0.093,0.17,0.374,0.11],"r":4.5333,"img":"img/E1/walk/p033_20_01.jpg","say":"캡션이에요. GS건설 '미사 강변 센트럴 자이' 예요."},{"b":[0.02,0.33,0.53,0.62],"c":[0,0.299,0.583,0.682],"r":1.1398,"img":"img/E1/walk/p033_20_02.jpg","say":"왼쪽 배치도예요. 빨간 점선이 단지 경계, 101부터 111까지가 동 번호예요."},{"b":[0.38,0.605,0.12,0.05],"c":[0.34,0.575,0.2,0.11],"r":2.4242,"img":"img/E1/walk/p033_20_03.jpg","say":"배치도 오른쪽에 **에코로드(Eco Road)**(산책로) 라고 적혀 있어요."},{"b":[0.565,0.265,0.39,0.72],"c":[0.5455,0.208,0.429,0.792],"r":0.7222,"img":"img/E1/walk/p033_20_04.jpg","say":"오른쪽 사진이에요. 건물 사이가 거의 다 녹지와 산책로예요."}]}},{"p":34,"title":"미사 강변 센트럴 자이: 물이 고인 잔디 정원","terms":["Rain Garden","Infiltration"],"pass1":[{"kind":"say","lines":["잔디밭 아래로 물이 고여 있는 사진이에요.","그냥 정원처럼 보이지만 빗물을 붙잡아 두는 **레인가든(Rain Garden)** 이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["주출입구가 둘뿐이고 지상에는 자동차가 못 다닌다고 하셨어요.","도로 쪽으로 완충녹지 띠를 둘렀대요.","그냥 잔디밭처럼 보이는 정원이 사실은 레인가든이라 빗물이 밑에 저장된다고 하셨어요."]}],"pass3":[{"kind":"check","q":"잔디밭처럼 보이지만 빗물을 밑에 저장하는 정원의 이름은?","choices":["**레인가든(Rain Garden)**","**에코로드(Eco Road)**","완충녹지","옥상정원"],"a":0,"why":"**레인가든(Rain Garden)** 은 빗물 저장기능을 가진 정원이에요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2422,0.063],"c":[0.039,0.0912,0.2664,0.095],"r":3.7389,"img":"img/E1/walk/p034_h.jpg"},"parts":[{"b":[0.11,0.205,0.34,0.04],"c":[0.093,0.17,0.374,0.11],"r":4.5333,"img":"img/E1/walk/p034_20_01.jpg","say":"캡션이에요. 앞 쪽과 같은 사례예요."},{"b":[0.105,0.34,0.79,0.595],"c":[0.0655,0.3102,0.869,0.6545],"r":1.7703,"img":"img/E1/walk/p034_20_02.jpg","say":"단지 안 정원이에요. 뒤로 아파트 동이 보여요."},{"b":[0.28,0.7,0.32,0.22],"c":[0.264,0.684,0.352,0.252],"r":1.8624,"img":"img/E1/walk/p034_20_03.jpg","say":"낮은 곳에 물이 고여 있어요. 빗물이 천천히 **침투(Infiltration)** 하는 자리예요."}]}},{"p":35,"title":"미사 강변 센트럴 자이: 생태연못과 커뮤니티","terms":["Crystal Garden","Habitat"],"pass1":[{"kind":"say","lines":["돌과 풀에 둘러싸인 작은 연못 사진이에요.","빗물로 만든 생태연못, **크리스탈 가든(Crystal Garden)** 이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["생태연못은 인공 분수대와 달리 수위를 조절하지 않는다고 하셨어요.","비가 오면 모였다가 흡수되는 그대로래요.","그래서 이 연못이 **크리스탈 가든(Crystal Garden)** 이에요."]}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2422,0.063],"c":[0.039,0.0912,0.2664,0.095],"r":3.7389,"img":"img/E1/walk/p035_h.jpg"},"parts":[{"b":[0.11,0.205,0.34,0.04],"c":[0.093,0.17,0.374,0.11],"r":4.5333,"img":"img/E1/walk/p035_20_01.jpg","say":"캡션이에요. 앞 쪽과 같은 사례예요."},{"b":[0.06,0.27,0.885,0.72],"c":[0.0157,0.208,0.9735,0.792],"r":1.6389,"img":"img/E1/walk/p035_20_02.jpg","say":"단지 가운데의 조경이에요. 오른쪽에 커뮤니티 건물이 붙어 있어요."},{"b":[0.38,0.6,0.3,0.2],"c":[0.365,0.584,0.33,0.232],"r":1.8966,"img":"img/E1/walk/p035_20_03.jpg","say":"가운데 얕은 연못이에요. 물가 식물과 돌이 생물의 **서식(Habitat)** 자리가 돼요."}]}},{"p":36,"title":"미사 강변 센트럴 자이: 위에서 본 생태연못","terms":["Crystal Garden","IFLA"],"pass1":[{"kind":"say","lines":["같은 연못을 조금 높은 곳에서 내려다본 사진이에요.","단풍나무와 물, 산책로가 한 덩어리로 이어져 있어요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["아스팔트는 비가 오면 하수도로 콸콸 흘러간다고 하셨어요.","흙길은 천천히 흡수되고, 물의 유출 속도를 늦추는 것이 홍수를 막는 가장 좋은 방법이래요."]}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2422,0.063],"c":[0.039,0.0912,0.2664,0.095],"r":3.7389,"img":"img/E1/walk/p036_h.jpg"},"parts":[{"b":[0.11,0.205,0.34,0.04],"c":[0.093,0.17,0.374,0.11],"r":4.5333,"img":"img/E1/walk/p036_20_01.jpg","say":"캡션이에요. 앞 쪽과 같은 사례예요."},{"b":[0.07,0.28,0.85,0.64],"c":[0.0275,0.248,0.935,0.704],"r":1.7708,"img":"img/E1/walk/p036_20_02.jpg","say":"단지 안 조경 전체가 보여요. 2019년 **세계조경가협회(IFLA)** 우수상을 받은 조경이에요."},{"b":[0.18,0.55,0.35,0.22],"c":[0.1625,0.534,0.385,0.252],"r":2.037,"img":"img/E1/walk/p036_20_03.jpg","say":"가운데가 **크리스탈 가든(Crystal Garden)** 이에요. 비가 오면 모였다가 스며들어요."}]}},{"p":37,"title":"소생태계(biotop, 비오톱)와 네 가지 분류","terms":["Biotop","Artificial Biotop","Habitat"],"pass1":[{"kind":"say","lines":["**비오톱(Biotop)** 은 생물이 사는 작은 집이에요.","건물을 지으면 자연이 훼손되니 사람이 새로 만들어 주기도 해요.","나누는 기준이 두 개예요. 물이냐 땅이냐, 저절로냐 사람 손이냐예요."]}],"pass2":[{"kind":"points","head":"용어 먼저","items":["**비오톱(Biotop)** 은 소생태계, 곧 생물의 **서식(Habitat)** 공간이에요.","bio(살아있는 생물) + top(영역, 지역) 이 합쳐진 말이에요.","**인공형 비오톱(Artificial Biotop)** 은 옥상정원처럼 사람이 새로 만들어 준 것이에요."]},{"kind":"points","head":"왜 만들까요?","items":["주택건축을 할 때 자연환경이 불가피하게 훼손되는 경우가 있어요.","그때 인위적으로 조성하여 자연을 복구해요.","그래서 **비오톱(Biotop)** 은 생물의 **서식(Habitat)** 을 돌려주는 일이에요."]},{"kind":"compare","head":"기준 두 개로 나눈 네 가지","cols":["기준","이름","예시"],"rows":[["물이냐 땅이냐","수생 비오톱","냇물가, 습지, 연못"],["물이냐 땅이냐","육생 비오톱","산림, 초지, 사막 등"],["저절로냐 사람 손이냐","자연형 비오톱","자연적으로 형성"],["저절로냐 사람 손이냐","**인공형 비오톱(Artificial Biotop)**","옥상정원 같이 새로 조성"]]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["비오톱은 소생태계, 생물의 서식 공간이라고 하셨어요.","녹지 파트에서 따로 배우니 지금은 비오톱이 무엇인지만 알면 된대요.","건축을 하면 자연환경은 무조건 훼손되니 인위적으로라도 복구하려다 보니 비오톱을 만들게 된다고 하셨어요."]}],"pass3":[{"kind":"check","q":"훼손된 산림 가장자리에 사람이 손대지 않았는데 초지가 저절로 생겼어요. 알맞은 이름은?","choices":["수생 자연형 비오톱","육생 인공형 비오톱","육생 자연형 비오톱","수생 인공형 비오톱"],"a":2,"why":"초지는 육생이고 저절로 생겼으니 자연형이에요. 옥상정원이라면 **인공형 비오톱(Artificial Biotop)** 이에요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"비오톱은 소생태계로 생물의 서식공간이며, bio(생물)와 top(영역)의 합성어다.","ko":"수생과 육생, 자연형과 **인공형 비오톱(Artificial Biotop)** 으로 나뉘어요.","tip":"물땅, 절로손 두 기준으로 나눠서 외워요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2422,0.063],"c":[0.039,0.0912,0.2664,0.095],"r":3.7389,"img":"img/E1/walk/p037_h.jpg"},"parts":[{"b":[0.11,0.245,0.29,0.042],"c":[0.0955,0.211,0.319,0.11],"r":3.8667,"img":"img/E1/walk/p037_23_01.jpg","say":"제목이에요. 소생태계(biotop, 비오톱) 예요."},{"b":[0.13,0.365,0.64,0.042],"c":[0.098,0.3149,0.704,0.1422],"r":6.601,"img":"img/E1/walk/p037_23_02.jpg","say":"생물의 서식공간 = bio + top 이라고 풀어 놓았어요."},{"b":[0.13,0.425,0.81,0.105],"c":[0.0895,0.3875,0.891,0.18],"r":6.6,"img":"img/E1/walk/p037_23_03.jpg","say":"주택건축 때 자연환경이 훼손되면 인위적으로 조성하여 자연을 복구해요."},{"b":[0.215,0.545,0.39,0.042],"c":[0.1955,0.511,0.429,0.11],"r":5.2,"img":"img/E1/walk/p037_23_04.jpg","say":"수생 비오톱이에요. 냇물가, 습지, 연못이에요."},{"b":[0.24,0.605,0.37,0.042],"c":[0.2215,0.571,0.407,0.11],"r":4.9333,"img":"img/E1/walk/p037_23_05.jpg","say":"육생 비오톱이에요. 산림, 초지, 사막 등이에요."},{"b":[0.22,0.665,0.48,0.105],"c":[0.196,0.649,0.528,0.137],"r":5.1387,"img":"img/E1/walk/p037_23_06.jpg","say":"자연형과 **인공형 비오톱(Artificial Biotop)** 이에요. 인공형 예시가 옥상정원이에요."}]}},{"p":38,"title":"비오톱 사진: 집 앞의 수생 비오톱","terms":["Biotop","Habitat"],"pass1":[{"kind":"say","lines":["집 바로 앞에 연못이 있고 물가에 풀이 우거진 사진이에요.","물이 있는 공간이니 수생 **비오톱(Biotop)** 이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["물이 있는 공간이 수생 비오톱이라고 하셨어요.","지금은 **비오톱(Biotop)** 이 무엇인지만 알면 된다고 하셨어요."]}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2422,0.063],"c":[0.039,0.0912,0.2664,0.095],"r":3.7389,"img":"img/E1/walk/p038_h.jpg"},"parts":[{"b":[0.11,0.245,0.29,0.045],"c":[0.0955,0.2125,0.319,0.11],"r":3.8667,"img":"img/E1/walk/p038_20_01.jpg","say":"캡션이에요. 소생태계(biotop, 비오톱) 예요."},{"b":[0.16,0.35,0.685,0.615],"c":[0.1258,0.3192,0.7535,0.6765],"r":1.4851,"img":"img/E1/walk/p038_20_02.jpg","say":"건물과 연못, 풀밭이 한 덩어리로 이어져 있어요."},{"b":[0.25,0.7,0.45,0.25],"c":[0.2275,0.684,0.495,0.282],"r":2.3404,"img":"img/E1/walk/p038_20_03.jpg","say":"물과 물가 식물이에요. 물속과 물가 생물의 **서식(Habitat)** 이 돼요."}]}},{"p":39,"title":"지붕녹화 사례 1: 정부세종청사 옥상정원","terms":["Roof Greening","Artificial Biotop"],"pass1":[{"kind":"say","lines":["건물 지붕 위가 통째로 정원인 사진이에요.","이것이 **지붕녹화(Roof Greening)** 이고, 정부세종청사 옥상정원이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["옥상정원 사례는 아주 많다고 하셨어요.","대표적으로 정부 세종청사의 옥상정원이 잘 되어 있다고 하셨어요."]}],"pass3":[{"kind":"check","q":"정부세종청사 옥상정원은 어느 순환체계의 사례일까요?","choices":["에너지 순환체계","녹지 순환체계","수 순환체계","대기 순환체계"],"a":1,"why":"**지붕녹화(Roof Greening)** 은 건축물 자체를 녹화하는 적극적 방법, 곧 녹지 순환체계예요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2422,0.063],"c":[0.039,0.0912,0.2664,0.095],"r":3.7389,"img":"img/E1/walk/p039_h.jpg"},"parts":[{"b":[0.08,0.245,0.41,0.042],"c":[0.0595,0.211,0.451,0.11],"r":5.4667,"img":"img/E1/walk/p039_20_01.jpg","say":"캡션이에요. 지붕녹화 : 정부세종청사 옥상정원이에요."},{"b":[0.205,0.355,0.595,0.54],"c":[0.1752,0.328,0.6545,0.594],"r":1.4691,"img":"img/E1/walk/p039_20_02.jpg","say":"여러 동의 지붕이 이어지고 그 위가 전부 녹지예요."},{"b":[0.25,0.6,0.45,0.25],"c":[0.2275,0.584,0.495,0.282],"r":2.3404,"img":"img/E1/walk/p039_20_03.jpg","say":"지붕 위 산책로와 화단이에요. 사람이 새로 만든 **인공형 비오톱(Artificial Biotop)** 이에요."}]}},{"p":40,"title":"정부세종청사 옥상정원: 지붕 위를 걷는 길","terms":["Roof Greening"],"pass1":[{"kind":"say","lines":["같은 옥상정원을 사람 눈높이에서 찍은 사진이에요.","지붕인데 공원처럼 길이 나 있고 사람이 걸어 다녀요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["옥상정원 사례는 아주 많다고 하셨어요.","그중 정부 세종청사의 옥상정원이 대표적으로 잘 되어 있다고 하셨어요."]}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2422,0.063],"c":[0.039,0.0912,0.2664,0.095],"r":3.7389,"img":"img/E1/walk/p040_h.jpg"},"parts":[{"b":[0.08,0.245,0.41,0.042],"c":[0.0595,0.211,0.451,0.11],"r":5.4667,"img":"img/E1/walk/p040_20_01.jpg","say":"캡션은 앞 쪽과 같아요. 정부세종청사 옥상정원이에요."},{"b":[0.01,0.32,0.98,0.67],"c":[0.0,0.263,1,0.737],"r":1.8091,"img":"img/E1/walk/p040_20_02.jpg","say":"지붕 위 녹지가 건물에서 건물로 계속 이어져요."},{"b":[0.3,0.52,0.35,0.18],"c":[0.2825,0.504,0.385,0.212],"r":2.4214,"img":"img/E1/walk/p040_20_03.jpg","say":"가운데 산책로예요. **지붕녹화(Roof Greening)** 위를 사람이 걸어 다녀요."}]}},{"p":41,"title":"지붕녹화 사례 2: 싱가포르 파크로얄호텔 (층별 지붕 녹화)","terms":["Roof Greening"],"pass1":[{"kind":"say","lines":["이번에는 지붕이 아니라 층마다 녹지가 얹혀 있어요.","싱가포르 파크로얄호텔의 층별 **지붕녹화(Roof Greening)** 이에요."]}],"pass2":[{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["해외에는 층별로 지붕 녹화를 한 사례도 있다고 하셨어요.","그 사례가 이 싱가포르 파크로얄호텔이에요."]}],"pass3":[{"kind":"warn","head":"헷갈리기 쉬운 점","items":["파크로얄호텔은 녹지 순환체계의 **지붕녹화(Roof Greening)** 사례예요. 대기나 물 사례가 아니에요.","정부세종청사는 옥상 한 면, 파크로얄호텔은 층별이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2422,0.063],"c":[0.039,0.0912,0.2664,0.095],"r":3.7389,"img":"img/E1/walk/p041_h.jpg"},"parts":[{"b":[0.08,0.228,0.6,0.042],"c":[0.05,0.1823,0.66,0.1333],"r":6.6017,"img":"img/E1/walk/p041_20_01.jpg","say":"캡션이에요. 지붕녹화 : 싱가포르, 파크로얄호텔 (층별 지붕 녹화) 예요."},{"b":[0.055,0.32,0.545,0.66],"c":[0.0277,0.274,0.5995,0.726],"r":1.101,"img":"img/E1/walk/p041_20_02.jpg","say":"왼쪽 사진이에요. 물결 모양 띠마다 나무와 풀이 심겨 있어요."},{"b":[0.605,0.455,0.36,0.34],"c":[0.587,0.438,0.396,0.374],"r":1.4118,"img":"img/E1/walk/p041_20_03.jpg","say":"오른쪽 사진이에요. 아래에서 올려다본 모습이에요."}]}},{"p":42,"title":"4) 수 순환체계: 우수는 저장 후 재활용, 오수는 정화 후 배출","terms":["Water Cycle","Rainwater","Wastewater","Infiltration","Rainwater Storage Facility","Water Purification","Circulation System"],"pass1":[{"kind":"say","lines":["다섯 순환 중 네 번째, 물 차례예요.","건물과 포장이 **수순환(Water Cycle)** 을 막는다는 이야기에서 시작해요.","빗물은 모아서 다시 쓰고, 더러운 물은 씻어서 내보내요.","주문: **자연에서 빌려 쓰고, 돌려주며 순환시켜요.**"]},{"kind":"analogy","head":"빌려 쓰고 돌려주는 물","scene":"건물은 사람 몸처럼 물을 마시고 내보내요. 빗물은 빌려 쓰고, 더럽힌 물은 씻어서 돌려줘요.","map":[["하늘에서 받은 물을 모아 다시 쓰기","**우수(Rainwater)** 저장 후 재활용"],["남은 물을 땅에 돌려주기","**우수(Rainwater)** 의 **침투(Infiltration)**"],["더럽힌 물은 씻어서 돌려주기","**오수(Wastewater)** 정화 후 배출"]]}],"pass2":[{"kind":"points","head":"용어 먼저","items":["**수순환(Water Cycle)** 은 비가 내려 스며들고 다시 증발해 하늘로 가는 물의 길이에요.","**우수(Rainwater)** 는 빗물, **오수(Wastewater)** 는 쓰고 난 더러워진 물이에요.","**침투(Infiltration)** 는 빗물이 흙 속으로 스며드는 것이에요.","**수질정화(Water Purification)** 는 더러운 물을 깨끗하게 만드는 일이에요."]},{"kind":"points","head":"시작과 기본","items":["건축물, 포장 등의 인공적인 구조물에 의해 **수순환(Water Cycle)** 을 저해하는 요소에 대한 고려에서부터 시작해요.","**우수(Rainwater)** 저장 후 재활용, **오수(Wastewater)** 정화 후 배출이 기본이에요.","이유는 물에 대한 오염방지와 순환성에 대한 배려예요."]},{"kind":"points","head":"방법 네 가지","items":["1) 빗물과 **오수(Wastewater)** 를 분리시켜 재사용하기 위한 설비시스템","2) 토양 밑으로 **침투(Infiltration)** 가능한 우수","3) **우수저장시설(Rainwater Storage Facility)**, **수질정화(Water Purification)** 및 재활용시설","4) 녹지체계와의 밀접한 관계. 앞글자로 분침시녹이에요."]},{"kind":"points","head":"**우수저장시설(Rainwater Storage Facility)** 의 효과 두 가지","items":["도시홍수의 피해를 줄여요.","물 부족 현상을 완화해요.","앞글자로 홍부예요. 둘 다 우수저장의 효과예요."]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["수순환의 핵심은 우수를 얼마큼 저장하느냐와 배출되는 오수를 얼마큼 정화하느냐래요.","방법은 먼저 빗물과 오수를 분리하는 것이에요. 안 그러면 하수도에서 다 섞인대요.","그다음 토양 밑으로 침투 가능한 대지를 만들고, 저장해 줄 시스템이 필요하대요.","동력 없이 알아서 해 주는 것이 녹지라서 녹지와 연계하면 완벽한 수순환 체계가 된대요."]}],"pass3":[{"kind":"check","q":"수 순환체계의 기본으로 맞는 것은?","choices":["우수는 정화 후 배출, 오수는 저장 후 재활용","우수는 저장 후 재활용, 오수는 정화 후 배출","우수와 오수를 함께 모아 한 번에 배출","우수는 하수도로 빨리 흘려보냄"],"a":1,"why":"**우수(Rainwater)** 는 저장 후 재활용, **오수(Wastewater)** 는 **수질정화(Water Purification)** 후 배출이에요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"우수저장의 효과는 도시홍수의 피해 저감과 물 부족 현상 완화다.","ko":"**우수저장시설(Rainwater Storage Facility)** 이 주는 효과 두 가지예요.","tip":"홍부 두 글자로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**우수(Rainwater)** 와 **오수(Wastewater)** 의 처리를 서로 바꾸면 틀려요.","도시홍수 저감과 물 부족 완화는 둘 다 **우수저장시설(Rainwater Storage Facility)** 의 효과예요.","네 번째 방법은 녹지체계와의 밀접한 관계예요. 다섯 **순환체계(Circulation System)** 은 서로 이어져 있어요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2144,0.063],"c":[0.0391,0.0912,0.2384,0.095],"r":3.346,"img":"img/E1/walk/p042_h.jpg"},"parts":[{"b":[0.11,0.245,0.84,0.105],"c":[0.068,0.2042,0.924,0.1867],"r":6.5988,"img":"img/E1/walk/p042_24_01.jpg","say":"시작 줄이에요. 인공 구조물이 **수순환(Water Cycle)** 을 막는 요소를 고려해요."},{"b":[0.11,0.365,0.83,0.105],"c":[0.0685,0.3253,0.913,0.1845],"r":6.598,"img":"img/E1/walk/p042_24_02.jpg","say":"기본 줄이에요. 저장 후 재활용과 정화 후 배출이에요."},{"b":[0.11,0.485,0.67,0.042],"c":[0.0765,0.4316,0.737,0.1489],"r":6.5995,"img":"img/E1/walk/p042_24_03.jpg","say":"방법 첫 줄이에요. 빗물과 오수를 분리시키는 설비시스템이에요."},{"b":[0.185,0.545,0.44,0.165],"c":[0.163,0.529,0.484,0.197],"r":3.2758,"img":"img/E1/walk/p042_24_04.jpg","say":"방법 둘째부터 넷째 줄이에요. **침투(Infiltration)**, 저장과 정화, 녹지 연계예요."},{"b":[0.11,0.725,0.29,0.165],"c":[0.0955,0.709,0.319,0.197],"r":2.1591,"img":"img/E1/walk/p042_24_05.jpg","say":"우수저장의 효과 두 가지예요. 도시홍수 저감과 물 부족 완화예요."},{"b":[0.63,0.55,0.36,0.42],"c":[0.604,0.529,0.396,0.462],"r":1.1429,"img":"img/E1/walk/p042_24_06.jpg","say":"오른쪽 그림이에요. 강수, 증발, 침투, 지하수가 도는 **수순환(Water Cycle)** 그림이에요."}]}},{"p":43,"title":"투수성 포장: 틈으로 물이 스며드는 바닥","terms":["Permeable Pavement","Infiltration"],"pass1":[{"kind":"say","lines":["블록 사이로 풀이 자라는 바닥 사진이에요.","이런 바닥이 **투수성 포장(Permeable Pavement)** 이에요.","아스팔트와 달리 빗물이 땅으로 들어갈 수 있어요."]}],"pass2":[{"kind":"points","head":"용어 먼저","items":["**투수성 포장(Permeable Pavement)** 은 블록 틈 같은 곳으로 빗물이 땅에 스며들게 만든 바닥 포장이에요.","빗물이 흙 속으로 들어가는 것을 **침투(Infiltration)** 라고 해요.","앞 쪽 방법 2, '토양 밑으로 침투 가능한 우수' 를 실제로 만든 것이에요."]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["투수성 포장은 아스팔트와 달리 어느 정도 물이 흡수된다고 하셨어요.","완전히 화강암 인도인 것과 이것이 있는 것의 차이가 꽤 크다고 하셨어요."]}],"pass3":[{"kind":"check","q":"**투수성 포장(Permeable Pavement)** 의 뜻으로 맞는 것은?","choices":["빗물이 틈으로 땅에 스며들게 만든 바닥 포장","빗물이 스며들지 않게 꽉 막은 아스팔트","빗물을 모아 두는 지하 탱크","지붕 위에 흙을 깔고 식물을 심은 것"],"a":0,"why":"**투수성 포장(Permeable Pavement)** 은 **침투(Infiltration)** 를 돕는 바닥이에요."}],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2144,0.063],"c":[0.0391,0.0912,0.2384,0.095],"r":3.346,"img":"img/E1/walk/p043_h.jpg"},"parts":[{"b":[0.11,0.245,0.15,0.042],"c":[0.085,0.211,0.2,0.11],"r":2.4242,"img":"img/E1/walk/p043_21_01.jpg","say":"캡션이에요. 투수성 포장이에요."},{"b":[0.085,0.335,0.355,0.3],"c":[0.0673,0.319,0.3905,0.332],"r":1.5683,"img":"img/E1/walk/p043_21_02.jpg","say":"왼쪽 위예요. 블록 사이 빈 칸에 흙과 풀이 있어요."},{"b":[0.085,0.64,0.355,0.295],"c":[0.0673,0.624,0.3905,0.327],"r":1.5923,"img":"img/E1/walk/p043_21_03.jpg","say":"왼쪽 아래예요. 네모 블록 사이를 풀이 채우고 있어요."},{"b":[0.455,0.395,0.49,0.47],"c":[0.4305,0.3715,0.539,0.517],"r":1.3901,"img":"img/E1/walk/p043_21_04.jpg","say":"오른쪽이에요. 왼쪽은 아스팔트, 오른쪽은 **투수성 포장(Permeable Pavement)** 이에요."}]}},{"p":44,"title":"투수성 레인가든: 보도 옆 화단이 빗물을 받아요","terms":["Rain Garden","Permeable Pavement","Infiltration"],"pass1":[{"kind":"say","lines":["비 오는 날 보도를 찍은 사진이에요.","가운데 길게 난 화단이 투수성 **레인가든(Rain Garden)** 이에요.","화강암 보도로 흐르던 빗물이 여기서 땅으로 들어가요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["보도블록 위로는 빗물이 그대로 흘러요.","가운데 화단은 낮게 파여 있어 빗물이 모이고 **침투(Infiltration)** 해요.","앞 쪽 **투수성 포장(Permeable Pavement)** 과 짝이 되는 사례예요.","**레인가든(Rain Garden)** 은 빗물 저장기능을 가진 정원이었어요."]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["광화문 인도의 나무 근처 잔디밭도 레인가든이라 투수성이 가능하다고 하셨어요.","완전히 화강암 인도인 것과 이것이 있는 것의 차이가 꽤 크다고 하셨어요."]}],"pass3":[],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2144,0.063],"c":[0.0391,0.0912,0.2384,0.095],"r":3.346,"img":"img/E1/walk/p044_h.jpg"},"parts":[{"b":[0.11,0.245,0.2,0.042],"c":[0.098,0.211,0.224,0.11],"r":2.7152,"img":"img/E1/walk/p044_21_01.jpg","say":"캡션이에요. 투수성 레인가든이에요."},{"b":[0.125,0.365,0.76,0.57],"c":[0.087,0.3365,0.836,0.627],"r":1.7778,"img":"img/E1/walk/p044_21_02.jpg","say":"비에 젖은 보도예요. 왼쪽은 물이 그대로 흐르는 포장이에요."},{"b":[0.42,0.5,0.25,0.42],"c":[0.4075,0.479,0.275,0.462],"r":0.7937,"img":"img/E1/walk/p044_21_03.jpg","say":"가운데 길게 난 화단이에요. 여기가 투수성 **레인가든(Rain Garden)** 이에요."}]}},{"p":45,"title":"우수저장시설 사례: 서울 스타시티 빗물 이용도","terms":["Rainwater Storage Facility","Rainwater","Water Cycle"],"pass1":[{"kind":"say","lines":["아파트 단지가 빗물을 어떻게 모아 쓰는지 그린 그림이에요.","서울 스타시티의 **우수저장시설(Rainwater Storage Facility)** 사례예요.","옥상에 떨어진 비가 지하 탱크로 가서 다시 쓰여요."]}],"pass2":[{"kind":"points","head":"그림의 번호 세 개","items":["1. 옥상 및 지표면에서 빗물을 취합해 아파트 지하의 탱크로 보내요.","2. 지상의 분수, 공용화장실, 스프링클러로 보내 재활용해요.","3. 스프링클러로 조경수에 쓴 빗물을 다시 취합해 지하 탱크로 보내요.","그래서 단지 안에서 작은 **수순환(Water Cycle)** 이 생겨요."]},{"kind":"points","head":"그림 아래 탱크 세 개","items":["지표 빗물 탱크, 옥상 빗물 탱크, 비상용 탱크예요.","앞의 둘은 **우수(Rainwater)** 이고, 비상용 탱크만 수돗물이에요.","왼쪽에는 수영장과 사우나, 분수와 스프링클러가 그려져 있어요."]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["건대입구 서울 스타시티는 옥상 빗물을 지하에 모아 쓰는 오래된 사례래요.","조경용수나 분수대 물로 쓴다고 하셨어요.","시험 범위로 공부하라는 것이 아니라 실제로 상용화되고 있다는 정도로 보면 된다고 하셨어요."]}],"pass3":[{"kind":"check","q":"서울 스타시티의 탱크 세 개 중 빗물이 아닌 것은?","choices":["지표 빗물 탱크","옥상 빗물 탱크","비상용 탱크","셋 다 빗물이다"],"a":2,"why":"비상용 탱크는 수돗물이에요. 나머지 둘이 **우수(Rainwater)** 탱크예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["스타시티는 물 사례예요. **우수저장시설(Rainwater Storage Facility)** 이지 지붕녹화 사례가 아니에요.","빗물을 먼저 쓰고, 모자랄 때를 위해 비상용 수돗물 탱크를 따로 둬요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2144,0.063],"c":[0.0391,0.0912,0.2384,0.095],"r":3.346,"img":"img/E1/walk/p045_h.jpg"},"parts":[{"b":[0.11,0.245,0.35,0.042],"c":[0.0925,0.211,0.385,0.11],"r":4.6667,"img":"img/E1/walk/p045_22_01.jpg","say":"캡션이에요. 우수저장 시설 : 서울 스타시티예요."},{"b":[0.14,0.365,0.19,0.04],"c":[0.128,0.33,0.214,0.11],"r":2.5939,"img":"img/E1/walk/p045_22_02.jpg","say":"그림 제목이에요. 스타시티 빗물 이용도예요."},{"b":[0.545,0.405,0.25,0.06],"c":[0.5325,0.38,0.275,0.11],"r":3.3333,"img":"img/E1/walk/p045_22_03.jpg","say":"1번이에요. 옥상과 지표면 빗물을 지하 탱크로 보내요."},{"b":[0.325,0.665,0.2,0.1],"c":[0.313,0.649,0.224,0.132],"r":2.2626,"img":"img/E1/walk/p045_22_04.jpg","say":"3번이에요. 조경수로 쓴 빗물을 다시 취합해요."},{"b":[0.51,0.745,0.35,0.12],"c":[0.4925,0.729,0.385,0.152],"r":3.3772,"img":"img/E1/walk/p045_22_05.jpg","say":"탱크 세 개예요. 지표 빗물, 옥상 빗물, 비상용(수돗물) 이에요."},{"b":[0.5,0.828,0.31,0.03],"c":[0.4845,0.788,0.341,0.11],"r":4.1333,"img":"img/E1/walk/p045_22_06.jpg","say":"2번이에요. 지상의 분수, 공용화장실, 스프링클러로 보내 재활용해요."}]}},{"p":46,"title":"5) 대기 순환체계: 온실가스 관리와 실내공기질 개선","terms":["Pollutant","Greenhouse Gas","Indoor Air Quality","VOCs","Pollution Source","Bake-out","Mechanical Ventilation System","Heat Recovery System","Circulation System"],"pass1":[{"kind":"say","lines":["다섯 순환의 마지막, 공기 차례예요.","목적이 둘인데 범위가 달라요. 하나는 지구, 하나는 실내예요.","지구 쪽은 **온실가스(Greenhouse Gas)**, 실내 쪽은 **실내공기질(Indoor Air Quality)** 예요."]},{"kind":"recap","items":["이것으로 다섯 **순환체계(Circulation System)** 이 다 나왔어요.","에너지, 재료, 녹지, 물, 대기 순서예요.","주문: **자연에서 빌려 쓰고, 돌려주며 순환시켜요.**"]}],"pass2":[{"kind":"points","head":"용어 먼저","items":["**공해물질(Pollutant)** 은 공기를 더럽혀 지구와 사람에게 해를 주는 물질이에요.","**온실가스(Greenhouse Gas)** 는 지구를 온실처럼 덥게 만드는 기체예요.","**휘발성유기화합물(VOCs)** 는 마감재 같은 화학재료에서 공기 중으로 날아 나오는 유해 물질이에요.","**오염원(Pollution Source)** 은 더러운 물질이 처음 나오는 곳, 곧 실내재료와 마감재예요."]},{"kind":"compare","head":"내용 및 목적 두 가지","cols":["목적","범위","하는 일"],"rows":[["**공해물질(Pollutant)** 관리","지구환경적 차원","**온실가스(Greenhouse Gas)** 관리하여 지구온난화에 대비하는 것"],["**실내공기질(Indoor Air Quality)** 개선","실내","**휘발성유기화합물(VOCs)** 등을 억제하여 건강한 실내 거주 조건 제공하는 것"]]},{"kind":"points","head":"굵게 강조된 세 줄","items":["공기는 지속적으로 정화되어야 해요.","내외부의 공기가 순환되어야 해요.","실내에서는 적정 환기 관리가 필요해요."]},{"kind":"points","head":"방법 네 가지","items":["1) 실내재료 및 마감재의 **오염원(Pollution Source)** 관리(화학재료)","2) **베이크아웃(Bake-out)** 기법","3) **기계적 환기시스템(Mechanical Ventilation System)**","4) **열회수시스템(Heat Recovery System)** 등. 앞글자로 오베기열이에요."]},{"kind":"look","walked":1},{"kind":"prof","when":"2주차 목요일 수업","lines":["대기 순환의 목적은 둘, 지구 환경 차원에서는 탄소를 줄이는 것, 인체 건강 차원에서는 실내 공기질이래요.","그러려면 환기를 해야 하는데 초고층을 지었더니 환기가 안 된다고 하셨어요.","방법은 먼저 오염원 관리예요. 휘발성유기화합물을 괜히 써서 새집증후군을 만들지 말라는 것이에요.","열회수 시스템은 단열이 되는 환기 시스템이라고 하셨어요."]}],"pass3":[{"kind":"check","q":"**휘발성유기화합물(VOCs)** 를 억제하는 것은 대기 순환체계의 어느 목적일까요?","choices":["지구환경적 차원의 공해물질 관리","실내공기질 개선","우수 저장 후 재활용","광역녹지체계와의 연계"],"a":1,"why":"**휘발성유기화합물(VOCs)** 등을 억제해 건강한 실내 거주 조건을 주는 것이 **실내공기질(Indoor Air Quality)** 개선이에요."},{"kind":"check","q":"대기 순환체계의 방법으로 슬라이드에 없는 것은?","choices":["실내재료 및 마감재의 오염원 관리","Bake-out 기법","기계적 환기시스템, 열회수시스템","투수성 포장"],"a":3,"why":"투수성 포장은 수 순환체계 사례예요. 대기의 방법은 **오염원(Pollution Source)** 관리와 **베이크아웃(Bake-out)** 부터 시작해요."},{"kind":"english","head":"시험 답안에 쓸 문장","en":"대기 순환체계의 방법은 오염원 관리, Bake-out 기법, 기계적 환기시스템, 열회수시스템이다.","ko":"목적은 **온실가스(Greenhouse Gas)** 관리와 **실내공기질(Indoor Air Quality)** 개선 두 가지예요.","tip":"오베기열 네 글자로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**온실가스(Greenhouse Gas)** 관리는 지구환경적 차원, **휘발성유기화합물(VOCs)** 억제는 실내예요. 짝을 바꾸면 틀려요.","**공해물질(Pollutant)** 관리와 **실내공기질(Indoor Air Quality)** 개선은 범위가 다른 두 목적이에요.","실내 공기를 밖과 차단하는 것이 아니라 내외부의 공기가 순환되어야 해요.","기계로 하는 환기가 **기계적 환기시스템(Mechanical Ventilation System)** 이에요.","나가는 공기의 열을 되살리는 것이 **열회수시스템(Heat Recovery System)** 이에요."]}],"pass4":[],"walk":{"head":{"b":[0.0511,0.1072,0.2422,0.063],"c":[0.039,0.0912,0.2664,0.095],"r":3.7389,"img":"img/E1/walk/p046_h.jpg"},"parts":[{"b":[0.11,0.245,0.53,0.042],"c":[0.0835,0.2071,0.583,0.1178],"r":6.5988,"img":"img/E1/walk/p046_24_01.jpg","say":"첫 줄이에요. 대기의 순환이 가능한 체계를 이루는 것이 중요해요."},{"b":[0.11,0.305,0.15,0.042],"c":[0.085,0.271,0.2,0.11],"r":2.4242,"img":"img/E1/walk/p046_24_02.jpg","say":"'내용 및 목적' 이라고 적힌 작은 제목이에요."},{"b":[0.13,0.365,0.59,0.105],"c":[0.1005,0.349,0.649,0.137],"r":6.3163,"img":"img/E1/walk/p046_24_03.jpg","say":"목적 1이에요. 지구환경적 차원의 **공해물질(Pollutant)** 관리, 곧 **온실가스(Greenhouse Gas)** 관리예요."},{"b":[0.13,0.485,0.71,0.105],"c":[0.0945,0.4586,0.781,0.1578],"r":6.5991,"img":"img/E1/walk/p046_24_04.jpg","say":"목적 2예요. **실내공기질(Indoor Air Quality)** 개선, 곧 **휘발성유기화합물(VOCs)** 등의 억제예요."},{"b":[0.085,0.665,0.8,0.105],"c":[0.045,0.6286,0.88,0.1778],"r":6.5992,"img":"img/E1/walk/p046_24_05.jpg","say":"굵은 글씨 줄이에요. 계속 정화, 안팎 순환, 실내는 적정 환기 관리예요."},{"b":[0.11,0.845,0.76,0.105],"c":[0.072,0.8131,0.836,0.1689],"r":6.5996,"img":"img/E1/walk/p046_24_06.jpg","say":"방법 네 가지예요. **오염원(Pollution Source)** 관리부터 **열회수시스템(Heat Recovery System)** 까지예요."}]}}]};
